// scripts/landmarks/straat-museum-builder.ts
function buildStraatMuseum(_w, _d, b) {
  const [lng0, lat0] = straat_museum_footprints_default.anchor;
  const ring = straat_museum_footprints_default.bag.geometry.coordinates[0].slice(0, -1).map(([lng, lat]) => new T16.Vector2((lng - lng0) * 111320 * Math.cos(lat0 * Math.PI / 180), -(lat - lat0) * 110540));
  const main = ring.slice(6, 20), office = [ring[19], ...ring.slice(0, 7)];
  b.add(openTopPrism(new T16.Shape(main), 0, 22.58), "greyBrick");
  b.add(openTopPrism(new T16.Shape(office), 0, 11.85), "greyBrick");
  const emit = (vertices, colour) => {
    const g = new T16.BufferGeometry();
    g.setAttribute("position", new T16.Float32BufferAttribute(vertices.flat(), 3));
    g.computeVertexNormals();
    b.add(g, colour);
  };
  const beam = (a, q, width2, colour) => {
    const start = new T16.Vector3(...a), end = new T16.Vector3(...q), delta = end.clone().sub(start), g = new T16.BoxGeometry(width2, width2, delta.length());
    g.applyQuaternion(new T16.Quaternion().setFromUnitVectors(new T16.Vector3(0, 0, 1), delta.clone().normalize()));
    const mid = start.add(end).multiplyScalar(0.5);
    b.add(g, colour, mid.x, mid.y, mid.z);
  };
  for (const roof of straat_museum_footprints_default.roofPlanes) {
    const flat = roof.rings.flat(), outer = roof.rings[0].map((p) => new T16.Vector2(p[0], p[2])), holes = roof.rings.slice(1).map((r) => r.map((p) => new T16.Vector2(p[0], p[2]))), sloped = roof.semantic.b3_hellingshoek > 30;
    for (const tri of T16.ShapeUtils.triangulateShape(outer, holes)) {
      let pts = tri.map((i) => flat[i]);
      const normal = new T16.Vector3(...pts[1]).sub(new T16.Vector3(...pts[0])).cross(new T16.Vector3(...pts[2]).sub(new T16.Vector3(...pts[0])));
      if (normal.y < 0) pts = [pts[0], pts[2], pts[1]];
      emit(pts, sloped ? "glass" : "slate");
    }
    if (sloped) {
      for (const r2 of roof.rings) for (let i = 0; i < r2.length; i++) beam(r2[i], r2[(i + 1) % r2.length], 0.14, "frame");
      const r = roof.rings[0], edges = r.map((p, i) => ({ a: p, q: r[(i + 1) % r.length], length: Math.hypot(r[(i + 1) % r.length][0] - p[0], r[(i + 1) % r.length][2] - p[2]) })).sort((a, q) => q.length - a.length);
      const lo = edges[0], hi = edges[1];
      if (lo && hi && lo.length > 20 && hi.length > 20) {
        let ha = hi.a, hq = hi.q;
        if (Math.hypot(lo.a[0] - ha[0], lo.a[2] - ha[2]) > Math.hypot(lo.a[0] - hq[0], lo.a[2] - hq[2])) [ha, hq] = [hq, ha];
        const count = Math.round(Math.min(lo.length, hi.length) / 2.8);
        for (let i = 1; i < count; i++) {
          const u = i / count;
          beam(lo.a.map((v, k) => v + (lo.q[k] - v) * u), ha.map((v, k) => v + (hq[k] - v) * u), 0.085, "frame");
        }
      }
    }
  }
  for (const end of straat_museum_footprints_default.roofEndWalls) {
    const r = end.rings[0], a = new T16.Vector3(...r[0]);
    let tangent = new T16.Vector2();
    for (const p of r) {
      tangent.set(p[0] - a.x, p[2] - a.z);
      if (tangent.length() > 0.01) break;
    }
    tangent.normalize();
    const xy = r.map((p) => new T16.Vector2((p[0] - a.x) * tangent.x + (p[2] - a.z) * tangent.y, p[1]));
    for (const tri of T16.ShapeUtils.triangulateShape(xy, [])) {
      const v = tri.map((i) => r[i]);
      emit(v, "slate");
      emit([v[0], v[2], v[1]], "slate");
    }
  }
  const area = ring.reduce((v, p, i) => {
    const q = ring[(i + 1) % ring.length];
    return v + p.x * q.y - q.x * p.y;
  }, 0), sign2 = Math.sign(area);
  function facade2(a, q) {
    const delta = q.clone().sub(a), length = delta.length(), t = delta.clone().normalize(), n = new T16.Vector2(t.y, -t.x).multiplyScalar(sign2), angle = -Math.atan2(t.y, t.x);
    return { length, point: (u, offset = 0.14) => a.clone().addScaledVector(t, u).addScaledVector(n, offset), box: (u, y, w, h, c, offset = 0.14, d = 0.16) => {
      const p = a.clone().addScaledVector(t, u).addScaledVector(n, offset);
      b.box(p.x, y, p.y, w, h, d, c, angle);
    } };
  }
  const front = facade2(ring[18], ring[9]), rear = facade2(ring[10], ring[14]), of = facade2(ring[2], ring[3]);
  const glazing = (f, y, h, spacing) => {
    f.box(f.length / 2, y, f.length - 0.3, h, "glass");
    for (const level of [y, y + h]) f.box(f.length / 2, level, f.length + 0.1, 0.18, "stone", 0.23, 0.2);
    const count = Math.round(f.length / spacing);
    for (let i = 0; i <= count; i++) f.box(f.length * i / count, y, 0.11, h, "stone", 0.25, 0.2);
  };
  for (const f of [front, rear]) {
    glazing(f, 18.35, 4, 1.45);
    f.box(f.length / 2, 22.45, f.length + 0.35, 0.22, "stone", 0.18, 0.36);
    for (let u = 3; u < f.length - 2; u += 6.7) {
      f.box(u, 13.5, 2.2, 2.6, "dark");
      for (let yy = 13.7; yy < 16; yy += 0.22) f.box(u, yy, 2.15, 0.065, "frame", 0.25, 0.12);
    }
  }
  for (const y of [4.8, 8.2]) glazing(of, y, 2.75, 1.8);
  for (const y of [4.35, 7.6]) of.box(of.length / 2, y, of.length, 0.55, "blue", 0.21, 0.18);
  of.box(of.length / 2, 11.7, of.length + 0.35, 0.3, "stone", 0.2, 0.45);
  for (let u = 3; u < of.length - 1; u += 2.55) {
    of.box(u, 0.15, 2.35, 3.85, "blue");
    of.box(u, 3.4, 2.1, 0.48, "glass", 0.25, 0.1);
    for (const du of [-1.2, 1.2]) of.box(u + du, 0.1, 0.08, 4.05, "frame", 0.3, 0.1);
  }
  const entry = facade2(ring[0], ring[2]);
  entry.box(entry.length * 0.6, 0, 1.7, 3, "blue");
  entry.box(entry.length * 0.6, 2.6, 1.7, 0.3, "stone", 0.24, 0.1);
  const sideWindow = entry.length * 0.6;
  for (const y of [4.8, 8.2]) {
    entry.box(sideWindow, y, 2.1, 2.75, "glass", 0.25, 0.12);
    for (const du of [-1.1, 0, 1.1]) entry.box(sideWindow + du, y - 0.05, 0.1, 2.85, "stone", 0.34, 0.12);
    for (const level of [y - 0.05, y + 1.37, y + 2.8]) entry.box(sideWindow, level, 2.3, 0.1, "stone", 0.34, 0.12);
  }
  for (const [a, q] of [[ring[14], ring[18]], [ring[9], ring[10]]]) {
    const f = facade2(a, q);
    for (let u = 8; u < f.length - 4; u += 9.6) {
      f.box(u, 4.1, 2.4, 2.65, "glass");
      for (const du of [-1.27, 0, 1.27]) f.box(u + du, 4.02, 0.13, 2.85, "white", 0.27, 0.2);
      for (const y of [4.02, 5.35, 6.8]) f.box(u, y, 2.66, 0.13, "white", 0.27, 0.2);
    }
    const door = f.length * 0.62;
    f.box(door, 0, 8.1, 10.8, "blue");
    for (const du of [-4.15, 0, 4.15]) f.box(door + du, 0, 0.15, 11, "frame", 0.26, 0.15);
    for (let u = 0; u < f.length; u += 17.5) f.box(u, 0, 0.14, 22.6, "frame", 0.14, 0.16);
  }
  const mf = front, centre = 8, width = 10.3, bottom = 4.2, height = 18.15;
  mf.box(centre, bottom, width, height, "pink", 0.34, 0.1);
  const patch = (points, c, depth = 0.43) => {
    const xy = points.map((p) => new T16.Vector2(p[0], p[1]));
    const flat = T16.ShapeUtils.triangulateShape(xy, []);
    for (const tri of flat) {
      const v = tri.map((i) => {
        const p = mf.point(centre + points[i][0], depth);
        return [p.x, bottom + points[i][1], p.y];
      });
      emit(v, c);
      emit([v[0], v[2], v[1]], c);
    }
  };
  patch([[-4.7, 0], [-4, 7], [0, 9], [4, 6], [4.9, 0]], "red");
  patch([[-3.5, 5], [-3.7, 12], [-2.5, 15.2], [1.7, 15.4], [3.4, 12.4], [3.1, 7.5], [0.5, 3.9]], "stone");
  const colours = ["blue", "gold", "green", "pink", "ochre"];
  for (let i = 0; i < 5; i++) {
    const x = -3.45 + i * 1.3;
    patch([[x, 7], [x + 0.9, 6], [x + 1.25, 13.5], [x + 0.1, 14.5]], colours[i], 0.46);
  }
  patch([[-4, 11.4], [-4.5, 14.3], [-3.4, 16.3], [-0.8, 17.5], [2.8, 16.5], [4, 13.9], [3.4, 11.5], [2.2, 14], [-2, 14.8]], "dark", 0.5);
  for (const x of [-1.9, 1.9]) {
    patch([[x - 1, 11.2], [x, 11.75], [x + 1, 11.2], [x, 10.75]], "white", 0.53);
    patch([[x - 0.38, 11.15], [x, 11.6], [x + 0.38, 11.15], [x, 10.9]], "dark", 0.56);
    patch([[x - 0.8, 12.1], [x + 0.5, 12.5], [x + 1, 12.05], [x - 0.9, 11.8]], "dark", 0.54);
  }
  patch([[-1.8, 8.2], [-0.8, 7.5], [1, 7.3], [2, 8.1], [1, 6.5], [-0.2, 6.2], [-1.3, 6.8]], "dark", 0.56);
  patch([[-1.3, 7.9], [1.6, 7.8], [0.9, 7.1], [-0.7, 7.2]], "white", 0.59);
  mf.box(centre, 0, width, 4.15, "glass", 0.38, 0.12);
  for (const u of [centre - width / 2, centre, centre + width / 2]) mf.box(u, 0, 0.15, 4.25, "frame", 0.5, 0.15);
  mf.box(centre, 4.1, width, 0.15, "frame", 0.5, 0.15);
}

