// scripts/landmarks/pllek-builder.ts
function buildPllek(_w, _d, { add: add2, box: box2 }) {
  const angle = 0.2, cos = Math.cos(angle), sin = Math.sin(angle);
  const native = (u, v) => new T18.Vector2(cos * u - sin * v, sin * u + cos * v);
  const uv = (p) => new T18.Vector2(cos * p[0] + sin * p[1], -sin * p[0] + cos * p[1]);
  const ring = pllek_footprints_default.outline[0].map(uv), shape3 = new T18.Shape(pllek_footprints_default.outline[0].map((p) => new T18.Vector2(p[0], p[1])));
  add2(openTopPrism(shape3, 0, 3), "dark");
  function clipped(minU, maxU, minV, maxV) {
    let r = ring.map((p) => p.clone());
    for (const [axis, value, keep] of [[0, minU, 1], [0, maxU, -1], [1, minV, 1], [1, maxV, -1]]) {
      const out2 = [];
      for (let i = 0; i < r.length; i++) {
        const p = r[i], q = r[(i + 1) % r.length], a = axis ? p.y : p.x, b = axis ? q.y : q.x, pa = (a - value) * keep >= -1e-6, qa = (b - value) * keep >= -1e-6;
        if (pa) out2.push(p);
        if (pa !== qa) out2.push(p.clone().lerp(q, (value - a) / (b - a)));
      }
      r = out2;
      if (!r.length) break;
    }
    return r;
  }
  function region(r, height, c) {
    if (r.length < 3) return;
    const sh = new T18.Shape(r.map((p) => native(p.x, p.y))), roof = upwardRoofPlane(sh);
    const pos = roof.getAttribute("position");
    for (let i = 0; i < pos.count; i++) {
      const u = cos * pos.getX(i) + sin * pos.getZ(i);
      pos.setY(i, height(u));
    }
    roof.computeVertexNormals();
    add2(roof, c);
    const walls = [];
    for (let i = 0; i < r.length; i++) {
      const p = r[i], q = r[(i + 1) % r.length], a = native(p.x, p.y), b = native(q.x, q.y);
      walls.push(a.x, 3, a.y, b.x, 3, b.y, b.x, height(q.x), b.y, a.x, 3, a.y, b.x, height(q.x), b.y, a.x, height(p.x), a.y);
    }
    const g = new T18.BufferGeometry();
    g.setAttribute("position", new T18.Float32BufferAttribute(walls, 3));
    g.computeVertexNormals();
    add2(g, c);
  }
  region(clipped(-40, 40, -20, -4.4), () => 5.55, "ochre");
  region(clipped(-15.7, 3.1, -4.4, 20), () => 3.5, "red");
  region(clipped(19.1, 40, -4.4, 20), () => 5.55, "blue");
  function barrel(minU, maxU, minV, maxV, eave, rise) {
    const n = 18;
    for (let i = 0; i < n; i++) {
      const ua = minU + (maxU - minU) * i / n, ub = minU + (maxU - minU) * (i + 1) / n;
      const height = (u) => eave + rise * Math.sin(Math.PI * (u - minU) / (maxU - minU));
      region(clipped(ua, ub, minV, maxV), height, "red");
    }
  }
  barrel(-26.8, -15.7, -4.4, 13.15, 4.35, 1.9);
  barrel(3.1, 19.1, -4.4, 7.6, 5.6, 2.2);
  function panel(u1, u2, v, y, h, c, offset = 0.06) {
    const m = native((u1 + u2) / 2, v + offset);
    add2(new T18.PlaneGeometry(u2 - u1, h), c, m.x, y + h / 2, m.y, -angle);
  }
  function glazed(a, b, v, h) {
    panel(a, b, v, 0, h, "frame");
    panel(a + 0.12, b - 0.12, v, 0.12, h - 0.24, "glass", 0.1);
    for (let u = a; u <= b; u += 2.6) {
      const p = native(u, v + 0.15);
      box2(p.x, 0, p.y, 0.12, h, 0.12, "frame");
    }
    panel(a, b, v, h - 0.1, 0.18, "frame", 0.17);
  }
  glazed(-26.65, -15.8, 13.13, 4.28);
  glazed(3.8, 18.15, 7.58, 5.52);
  glazed(-3, -1.3, 7.55, 2.95);
  for (let i = 0; i < ring.length; i++) {
    const a = ring[i], b = ring[(i + 1) % ring.length], delta = b.clone().sub(a), len = delta.length();
    if (len < 0.35) continue;
    const mid = a.clone().add(b).multiplyScalar(0.5), front = delta.x > 0 && Math.abs(delta.x) > Math.abs(delta.y) && mid.y > 0;
    if (front && (mid.x < -15.7 || mid.x > 3.1 && mid.x < 19.1)) continue;
    const height = mid.y < -4.4 || mid.x > 19.1 ? 5.55 : 3.45;
    const c = mid.y < -4.4 ? "ochre" : mid.x > 19.1 ? "blue" : "red";
    const tangent = delta.clone().normalize(), normal = new T18.Vector2(-tangent.y, tangent.x);
    const backing = mid.clone().addScaledVector(normal, 0.018), back = native(backing.x, backing.y), endA = native(a.x, a.y), endB = native(b.x, b.y);
    add2(new T18.PlaneGeometry(len, height), c, back.x, height / 2, back.y, Math.atan2(-(endB.y - endA.y), endB.x - endA.x));
    for (let d = 0.15; d < len; d += 0.32) {
      const p = a.clone().addScaledVector(tangent, d).addScaledVector(normal, 0.035), n = native(p.x, p.y);
      box2(n.x, 0, n.y, 0.055, height, 0.055, c);
    }
    const pa = a.clone().addScaledVector(normal, 0.05), pb = b.clone().addScaledVector(normal, 0.05), na = native(pa.x, pa.y), nb = native(pb.x, pb.y), m = na.clone().add(nb).multiplyScalar(0.5), rot = Math.atan2(-(nb.y - na.y), nb.x - na.x);
    for (const y of [0.08, 2.72, 5.4].filter((y2) => y2 < height)) box2(m.x, y, m.y, len, 0.1, 0.1, "frame", rot);
  }
  const tower = clipped(0.95, 3.75, -7.3, -4.8);
  region(tower, () => 12.55, "ochre");
  for (let y = 6; y < 12.3; y += 0.32) {
    const a = native(1.2, -4.7), b = native(3.5, -4.7), m = a.clone().add(b).multiplyScalar(0.5);
    box2(m.x, y, m.y, 2.3, 0.06, 0.06, "frame", -angle);
  }
}

