// scripts/landmarks/jeruzalemkerk-builder.ts
function buildJeruzalemkerk(_w, _d, b) {
  const a = jeruzalemkerk_footprints_default.authorAngleRadians;
  const at = (x, z) => [x * Math.cos(a) + z * Math.sin(a), -x * Math.sin(a) + z * Math.cos(a)];
  function add2(g, c, x = 0, y = 0, z = 0, angle = 0) {
    const p = at(x, z);
    b.add(g, c, p[0], y, p[1], a + angle);
  }
  function box2(x, y, z, w, h, d, c, angle = 0) {
    const p = at(x, z);
    b.box(p[0], y, p[1], w, h, d, c, a + angle);
  }
  function shape3(rings) {
    const s = new T29.Shape(rings[0].map((p) => new T29.Vector2(p[0], p[1])));
    for (const r of rings.slice(1)) s.holes.push(new T29.Path(r.map((p) => new T29.Vector2(p[0], p[1]))));
    return s;
  }
  function prism2(rings, h, c = "brick", base = 0) {
    const s = shape3(rings), wall = openTopPrism(s, base, h), roof = upwardRoofPlane(s, h);
    wall.userData.role = "shell";
    roof.userData.role = "roof";
    add2(wall, c);
    add2(roof, "slate");
  }
  function mass(x, z, w, d, h, c = "brick", base = 0) {
    prism2([[[x - w / 2, z - d / 2], [x + w / 2, z - d / 2], [x + w / 2, z + d / 2], [x - w / 2, z + d / 2]]], h, c, base);
  }
  prism2(jeruzalemkerk_footprints_default.parts[0].localRings, 3.5, "brick");
  mass(0, 0.45, 13.3, 20.8, 14.18);
  for (const s of [-1, 1]) {
    mass(s * 8.8, -1.5, 4.25, 12.85, 9.9);
    mass(s * 8.04, 7.8, 2.72, 5.85, 7.85);
  }
  mass(-0.05, 11.63, 12.75, 2.7, 14.18);
  box2(-0.05, 14.18, 12.97, 12.97, 0.18, 0.35, "stone");
  box2(0, 0.15, 13.22, 12.72, 3.45, 0.15, "greyBrick");
  box2(0, 3.6, 13.29, 12.77, 0.15, 0.22, "stone");
  for (const s of [-1, 1]) {
    box2(s * 8, 7.85, 10.81, 2.88, 0.15, 0.32, "stone");
    box2(s * 10.94, 9.9, -1.5, 0.24, 0.16, 12.9, "stone");
  }
  mass(0, 12.9, 3.45, 0.72, 14.8, "brick", 3.5);
  function window2(x, y, z, w, h, angle = 0, trim = "frame") {
    box2(x, y - 0.06, z, w + 0.17, h + 0.12, 0.1, trim, angle);
    box2(x, y, z + 0.11, w, h, 0.08, "glass", angle);
    for (let j = 0.43; j < h; j += 0.45) box2(x, y + j, z + 0.18, w, 0.045, 0.06, "dark", angle);
  }
  for (const x of [-1.02, 0, 1.02]) window2(x, 5.05, 13.36, 0.7, 5.72);
  for (const x of [-1.53, -0.51, 0.51, 1.53]) box2(x, 4.58, 13.37, 0.16, 8.1, 0.35, "brick");
  for (const x of [-1.02, 0, 1.02]) {
    const g = new T29.BoxGeometry(0.77, 0.16, 0.42);
    g.rotateX(-0.32);
    add2(g, "brick", x, 4.94, 13.39);
  }
  mass(0, 12, 3.65, 2.2, 15.05, "brick", 14.18);
  for (const x of [-1.7, 0, 1.7]) box2(x, 15.05, 12, 0.35, 2.76, 2, "brick");
  box2(0, 15.05, 11.12, 3.64, 2.1, 0.23, "brick");
  box2(0, 17.15, 12, 3.85, 0.18, 2.3, "stone");
  for (const x of [-1.7, 0, 1.7]) box2(x, 17.33, 12, 0.35, 0.65, 2, "brick");
  for (const x of [-0.85, 0.85]) for (const y of [15.38, 15.73, 16.08, 16.43]) box2(x, y, 12.82, 1.28, 0.1, 0.28, "dark");
  for (const s of [-1, 1]) for (let y = 12.3; y < 13.8; y += 0.27) box2(s * 2.08, y, 13, 0.38, 0.17, 0.28, "stone");
  for (const x of [-3.33, 0, 3.33]) {
    box2(x, 0.25, 13.37, 1.93, 2.2, 0.12, "dark");
    for (const dx of [-0.62, 0.62]) box2(x + dx, 0.32, 13.47, 0.085, 2.06, 0.08, "ochre");
    box2(x, 0.32, 13.47, 0.1, 2.06, 0.08, "ochre");
    box2(x, 2.46, 13.47, 2, 0.16, 0.28, "brick");
  }
  for (let i = 0; i < 3; i++) box2(0, i * 0.12, 13.6 + (2 - i) * 0.3, 12.6, 0.12, 0.3, "stone");
  for (const s of [-1, 1]) {
    for (let i = 0; i < 7; i++) {
      const z = -6.45 + i * 1.64;
      const xx = s * 11.03;
      box2(xx, 4.3, z, 0.1, 4.42, 1.12, "dark");
      box2(xx + s * 0.11, 4.36, z, 0.08, 4.26, 1.04, "glass");
      for (let y = 4.7; y < 8.6; y += 0.43) box2(xx + s * 0.18, y, z, 0.07, 0.045, 1.04, "dark");
      box2(xx + s * 0.07, 1.9, z, 0.15, 1.04, 1.13, "stone");
      box2(xx + s * 0.18, 2, z, 0.06, 0.84, 0.94, "glass");
      if (i < 6) box2(s * 11.13, 3.55, z + 0.82, 0.42, 6.8, 0.28, "brick");
    }
    box2(s * 11.1, 1.51, -1.5, 0.29, 0.16, 12.5, "stone");
    for (const dx of [-0.53, 0, 0.53]) window2(s * 8.04 + dx, 1.18, 10.91, 0.38, 4.45);
    box2(s * 9.5, 0.35, 6.9, 0.11, 2.35, 1.36, "dark");
    box2(s * 9.8, 2.84, 6.9, 0.88, 0.17, 1.68, "stone");
  }
  for (const part of jeruzalemkerk_footprints_default.parts.slice(1)) {
    prism2(part.localRings, 16.35);
    const ring = part.localRings[0];
    for (let i = 0; i < ring.length; i++) {
      const p = ring[i], q = ring[(i + 1) % ring.length], dx = q[0] - p[0], dz = q[1] - p[1], len = Math.hypot(dx, dz);
      if (len < 5.8) continue;
      const angle = Math.atan2(-dz, dx), nx = dz / len, nz = -dx / len;
      const area = ring.reduce((v, p2, j) => {
        const q2 = ring[(j + 1) % ring.length];
        return v + p2[0] * q2[1] - q2[0] * p2[1];
      }, 0), out2 = area > 0 ? 1 : -1;
      for (const t of [0.27, 0.72]) for (const [y, h] of [[0.8, 2.15], [4.1, 1.75], [7.2, 1.75], [10.3, 1.75], [13.55, 1.35]]) {
        const x = p[0] + dx * t + nx * out2 * 0.14, z = p[1] + dz * t + nz * out2 * 0.14;
        box2(x, y - 0.06, z, 1.82, h + 0.12, 0.12, "white", angle);
        box2(x + nx * out2 * 0.12, y, z + nz * out2 * 0.12, 1.6, h, 0.08, "glass", angle);
        box2(x + nx * out2 * 0.18, y + h * 0.5, z + nz * out2 * 0.18, 1.63, 0.065, 0.06, "white", angle);
      }
    }
  }
  for (const s of [-1, 1]) {
    box2(s * 12, 0, 1, 0.2, 0.4, 24, "greyBrick");
    for (let z = -11; z < 13; z += 0.7) box2(s * 12, 0.4, z, 0.055, 0.75, 0.055, "dark");
    box2(s * 12, 1.08, 1, 0.08, 0.07, 24, "dark");
  }
}

