// scripts/landmarks/blauwe-theehuis-builder.ts
function buildBlauweTheehuis(_w, _d, b) {
  const [lng0, lat0] = blauwe_theehuis_footprints_default.anchor;
  const local = ([lng, lat]) => new T31.Vector2((lng - lng0) * 111320 * Math.cos(lat0 * Math.PI / 180), -(lat - lat0) * 110540);
  const core = blauwe_theehuis_footprints_default.bag.geometry.coordinates[0].slice(0, -1).map(local);
  const terrace = blauwe_theehuis_footprints_default.terraceRing.slice(0, -1).map(local);
  const winding = Math.sign(core.reduce((sum, p, i) => {
    const q = core[(i + 1) % core.length];
    return sum + p.x * q.y - q.x * p.y;
  }, 0));
  const shape3 = (ring) => new T31.Shape(ring);
  const slab = (ring, y, h, c) => {
    b.add(openTopPrism(shape3(ring), y, y + h), c);
    b.add(upwardRoofPlane(shape3(ring), y + h), c);
  };
  const circle = (r, n = 64) => Array.from({ length: n }, (_, i) => new T31.Vector2(r * Math.cos(i * 2 * Math.PI / n), r * Math.sin(i * 2 * Math.PI / n)));
  const beam = (a, q, r, c) => {
    const d = q.clone().sub(a), g = new T31.CylinderGeometry(r, r, d.length(), 6);
    g.applyQuaternion(new T31.Quaternion().setFromUnitVectors(new T31.Vector3(0, 1, 0), d.clone().normalize()));
    const m = a.clone().add(q).multiplyScalar(0.5);
    b.add(g, c, m.x, m.y, m.z);
  };
  slab(terrace, 0, 0.18, "concrete");
  slab(circle(9.9), 0.18, 0.16, "concrete");
  b.add(openTopPrism(shape3(core), 0.34, 3.25), "white");
  slab(terrace, 3.25, 0.22, "white");
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI / 6, x = 8.1 * Math.cos(a), z = 8.1 * Math.sin(a);
    b.add(new T31.CylinderGeometry(0.095, 0.095, 2.91, 8), "blue", x, 1.795, z);
    for (let j = 0; j < 4; j++) {
      const t = j * Math.PI / 2;
      b.add(new T31.SphereGeometry(0.105, 6, 4), "white", x + 0.2 * Math.cos(t), 3.1, z + 0.2 * Math.sin(t));
    }
  }
  for (let i = 0; i < core.length; i++) {
    const a = core[i], q = core[(i + 1) % core.length], len = a.distanceTo(q);
    if (len < 0.6) continue;
    const m = a.clone().add(q).multiplyScalar(0.5), normal = new T31.Vector2(q.y - a.y, a.x - q.x).normalize().multiplyScalar(0.065 * winding), angle = -Math.atan2(q.y - a.y, q.x - a.x);
    if (len > 1) {
      b.box(m.x + normal.x, 0.82, m.y + normal.y, len * 0.78, 2.15, 0.09, "glass", angle);
      for (const y of [0.78, 2.75]) b.box(m.x + normal.x, y, m.y + normal.y, len * 0.84, 0.09, 0.13, "blue", angle);
      for (const t of [0.13, 0.5, 0.87]) {
        const p = a.clone().lerp(q, t).add(normal);
        b.box(p.x, 0.78, p.y, 0.09, 2.17, 0.12, "blue", angle);
      }
    }
  }
  const upper = circle(4.6, 12);
  slab(upper, 3.47, 0.45, "white");
  for (let i = 0; i < 12; i++) {
    const a = upper[i], q = upper[(i + 1) % 12], m = a.clone().add(q).multiplyScalar(0.5), len = a.distanceTo(q), angle = -Math.atan2(q.y - a.y, q.x - a.x);
    b.box(m.x, 3.92, m.y, len, 2.12, 0.12, "glass", angle);
    for (const t of [0, 1 / 3, 2 / 3]) {
      const p = a.clone().lerp(q, t);
      b.box(p.x, 3.86, p.y, 0.11, 2.31, 0.14, "blue", angle);
    }
    for (const y of [3.87, 5.68, 6.12]) b.box(m.x, y, m.y, len, 0.11, 0.15, "blue", angle);
  }
  slab(circle(6.1), 6.15, 0.23, "white");
  const crown = shape3(circle(6));
  crown.holes.push(new T31.Path(circle(5.63).reverse()));
  b.add(openTopPrism(crown, 7.12, 7.3), "blue");
  b.add(upwardRoofPlane(crown, 7.3), "blue");
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI / 6;
    b.box(5.43 * Math.cos(a), 6.38, 5.43 * Math.sin(a), 0.17, 0.74, 0.17, "white");
  }
  for (let i = 0; i < 64; i++) {
    const a = i * 2 * Math.PI / 64, q = (i + 1) * 2 * Math.PI / 64;
    if (i >= 23 && i <= 26) continue;
    const p = (t, y) => new T31.Vector3(9.8 * Math.cos(t), y, 9.8 * Math.sin(t));
    beam(p(a, 4.53), p(q, 4.53), 0.055, "blue");
    beam(p(a, 3.61), p(a, 4.53), 0.035, "blue");
  }
  const rot = -3 * Math.PI / 4, origin = new T31.Vector3(-7.6, 0, -7.6), dir = new T31.Vector3(Math.cos(rot), 0, -Math.sin(rot));
  for (let i = 0; i < 18; i++) {
    const m = origin.clone().addScaledVector(dir, (17 - i) * 0.25);
    b.box(m.x, 0.34 + i * 0.174, m.z, 1.4, 0.09, 0.29, "slate", rot + Math.PI / 2);
  }
  for (const s of [-1, 1]) {
    const side = new T31.Vector3(-dir.z, 0, dir.x).multiplyScalar(s * 0.66);
    const a = origin.clone().addScaledVector(dir, 4.35).add(side);
    a.y = 1.32;
    const q = origin.clone().add(side);
    q.y = 4.46;
    beam(a, q, 0.047, "blue");
  }
}

