// scripts/landmarks/beest-het-lab-builder.ts
function buildBeestHetLab(_w, _d, { add: add2, box: box2 }) {
  const outline = beest_het_lab_footprints_default.outline[0].map((p) => new T32.Vector2(p[0], p[1]));
  add2(openTopPrism(new T32.Shape(outline), 0, 3.12), "greyBrick");
  for (const roof of beest_het_lab_footprints_default.roofs) {
    const r = roof.rings[0], cx2 = r.reduce((s, p) => s + p[0], 0) / r.length, cz = r.reduce((s, p) => s + p[1], 0) / r.length, cy = r.reduce((s, p) => s + p[2], 0) / r.length;
    let xx = 0, xz = 0, zz = 0, xy = 0, zy = 0;
    for (const p of r) {
      const x = p[0] - cx2, z = p[1] - cz, y = p[2] - cy;
      xx += x * x;
      xz += x * z;
      zz += z * z;
      xy += x * y;
      zy += z * y;
    }
    const det = xx * zz - xz * xz, a = (xy * zz - zy * xz) / det, b = (zy * xx - xy * xz) / det;
    const height = (x, z) => cy + a * (x - cx2) + b * (z - cz);
    const shape3 = new T32.Shape(r.map((p) => new T32.Vector2(p[0], p[1])));
    for (const hole of roof.rings.slice(1)) shape3.holes.push(new T32.Path(hole.map((p) => new T32.Vector2(p[0], p[1]))));
    const top = upwardRoofPlane(shape3);
    const positions = top.getAttribute("position");
    for (let i = 0; i < positions.count; i++) positions.setY(i, height(positions.getX(i), positions.getZ(i)));
    top.computeVertexNormals();
    add2(top, "slate");
    const walls = [];
    for (const ring2 of roof.rings) for (let i = 0; i < ring2.length; i++) {
      const p = ring2[i], q = ring2[(i + 1) % ring2.length], hp = height(p[0], p[1]), hq = height(q[0], q[1]);
      walls.push(p[0], 3.12, p[1], q[0], 3.12, q[1], q[0], hq, q[1], p[0], 3.12, p[1], q[0], hq, q[1], p[0], hp, p[1]);
    }
    const g = new T32.BufferGeometry();
    g.setAttribute("position", new T32.Float32BufferAttribute(walls, 3));
    g.computeVertexNormals();
    add2(g, "greyBrick");
  }
  function panel(p, q, y, h, c, offset = 0.05) {
    const tangent2 = q.clone().sub(p).normalize(), normal = new T32.Vector2(-tangent2.y, tangent2.x), mid = p.clone().add(q).multiplyScalar(0.5).addScaledVector(normal, offset), ang = Math.atan2(-tangent2.y, tangent2.x);
    add2(new T32.PlaneGeometry(p.distanceTo(q), h), c, mid.x, y + h / 2, mid.y, ang);
  }
  function ribbon(p, q, y, h, offset = 0.05) {
    panel(p, q, y - 0.08, h + 0.16, "white", offset);
    panel(p, q, y, h, "glass", offset + 0.04);
    const length = p.distanceTo(q), n = Math.ceil(length / 2.4);
    for (let i = 0; i <= n; i++) {
      const m = p.clone().lerp(q, i / n), d = q.clone().sub(p).normalize(), normal = new T32.Vector2(-d.y, d.x);
      m.addScaledVector(normal, offset + 0.08);
      box2(m.x, y, m.y, 0.12, h, 0.12, "white");
    }
  }
  const frontA = new T32.Vector2(-19.4, 36.5), frontB = new T32.Vector2(17, 35.5);
  ribbon(frontA, frontB, 4.12, 1.25);
  panel(frontA, frontB, 5.44, 0.24, "white", 0.15);
  const tangent = frontB.clone().sub(frontA).normalize(), frontPoint = (x) => frontA.clone().addScaledVector(tangent, x + 19.4);
  const shutterA = frontPoint(-0.5), shutterB = frontPoint(5.6);
  panel(shutterA, shutterB, 0.08, 3, "frame");
  panel(shutterA, shutterB, 0.15, 2.83, "concrete", 0.1);
  for (let y = 0.25; y < 2.95; y += 0.17) panel(shutterA, shutterB, y, 0.035, "frame", 0.13);
  const da = frontPoint(11.1), db = frontPoint(13.4);
  panel(da, db, 0.12, 2.9, "frame");
  panel(da, db, 0.22, 2.7, "glass", 0.12);
  const high = beest_het_lab_footprints_default.roofs.find((roof) => roof.rings[0].every((p) => p[2] > 9.25));
  const ring = high.rings[0];
  for (let i = 0; i < ring.length; i++) {
    const p = ring[i], q = ring[(i + 1) % ring.length];
    if (Math.hypot(q[0] - p[0], q[1] - p[1]) < 2) continue;
    const a = new T32.Vector2(p[0], p[1]), b = new T32.Vector2(q[0], q[1]);
    ribbon(a, b, 6.15, 2.1);
    panel(a, b, 8.3, 1, "white", 0.12);
  }
  const officeA = new T32.Vector2(-11.107, 33.777), officeB = new T32.Vector2(6.51, 33.302);
  ribbon(officeA, officeB, 6.15, 2.1, 0.55);
  panel(officeA, officeB, 8.3, 1, "white", 0.62);
  for (const p of [officeA, officeB]) box2(p.x, 5.6, p.y + 0.35, 0.18, 3.7, 0.72, "white");
  ribbon(new T32.Vector2(-21.3, -31.8), new T32.Vector2(-19.4, 36.5), 4.15, 1.2);
  ribbon(new T32.Vector2(20.2, -36.6), new T32.Vector2(-21.1, -35.4), 2.15, 1);
}

