// scripts/landmarks/kinderkookkafe-builder.ts
function buildKinderkookkafe(_w, _d, b) {
  const emit = (points, colour) => {
    const g = new T34.BufferGeometry();
    g.setAttribute("position", new T34.Float32BufferAttribute(points.flat(), 3));
    g.computeVertexNormals();
    b.add(g, colour);
  };
  const beam = (a, q, w, c) => {
    const d = q.clone().sub(a), g = new T34.BoxGeometry(w, w, d.length());
    g.applyQuaternion(new T34.Quaternion().setFromUnitVectors(new T34.Vector3(0, 0, 1), d.clone().normalize()));
    const p = a.clone().add(q).multiplyScalar(0.5);
    b.add(g, c, p.x, p.y, p.z);
  };
  for (const [partIndex, part] of kinderkookkafe_footprints_default.parts.entries()) {
    const ring = part.ring.map((p) => new T34.Vector2(...p));
    const sign2 = Math.sign(ring.reduce((s, p, i) => {
      const q = ring[(i + 1) % ring.length];
      return s + p.x * q.y - q.x * p.y;
    }, 0));
    const roofAt = (p) => {
      let nearest = Infinity, h = 3.7;
      for (const roof of part.roofs) for (const r of roof.rings) for (let i = 0; i < r.length; i++) {
        const a = r[i], q = r[(i + 1) % r.length], v = new T34.Vector2(q[0] - a[0], q[2] - a[2]), u = T34.MathUtils.clamp(p.clone().sub(new T34.Vector2(a[0], a[2])).dot(v) / v.lengthSq(), 0, 1), distance2 = p.distanceTo(new T34.Vector2(a[0] + v.x * u, a[2] + v.y * u));
        if (distance2 < nearest) {
          nearest = distance2;
          h = a[1] + u * (q[1] - a[1]);
        }
      }
      return h;
    };
    for (const [roofIndex, roof] of part.roofs.entries()) for (const r of roof.rings) {
      const flat = r.map((p) => new T34.Vector2(p[0], p[2]));
      for (const ids of T34.ShapeUtils.triangulateShape(flat, [])) {
        let pts = ids.map((i) => r[i]);
        const a = new T34.Vector3(...pts[0]), q = new T34.Vector3(...pts[1]), v = new T34.Vector3(...pts[2]);
        if (q.sub(a).cross(v.sub(a)).y < 0) pts = [pts[0], pts[2], pts[1]];
        emit(pts, partIndex === 0 && roofIndex === 0 ? "glass" : "slate");
      }
    }
    const same = (a, q) => Math.hypot(a[0] - q[0], a[2] - q[2]) < 0.025;
    for (let k = 0; k < part.roofs.length; k++) for (let l = k + 1; l < part.roofs.length; l++) {
      const r = part.roofs[k].rings[0], t = part.roofs[l].rings[0];
      for (let i = 0; i < r.length; i++) for (let j = 0; j < t.length; j++) {
        const a = r[i], q = r[(i + 1) % r.length], u = t[j], v = t[(j + 1) % t.length];
        const pair = same(a, u) && same(q, v) ? [u, v] : same(a, v) && same(q, u) ? [v, u] : null;
        if (!pair || Math.max(Math.abs(a[1] - pair[0][1]), Math.abs(q[1] - pair[1][1])) < 0.05) continue;
        const pts = [a, q, pair[1], a, pair[1], pair[0]];
        emit(pts, "brick");
        emit([pts[0], pts[2], pts[1], pts[3], pts[5], pts[4]], "brick");
      }
    }
    const facade2 = (i, end = (i + 1) % ring.length) => {
      const a = ring[i], q = ring[end], d = q.clone().sub(a), length = d.length(), n = new T34.Vector2(d.y, -d.x).normalize().multiplyScalar(sign2), angle = -Math.atan2(d.y, d.x);
      return { a, q, d, length, n, angle, point: (u, offset = 0) => a.clone().lerp(q, u).addScaledVector(n, offset) };
    };
    for (let i = 0; i < ring.length; i++) {
      const f2 = facade2(i), { a, q, length, n, angle, point } = f2;
      const glass = partIndex === 0 && [2, 3, 4, 5].includes(i), steps2 = Math.max(1, Math.ceil(length / 0.25));
      for (let j = 0; j < steps2; j++) {
        const p = a.clone().lerp(q, j / steps2), s = a.clone().lerp(q, (j + 1) / steps2), hp = roofAt(p), hs = roofAt(s), pts = [[p.x, 0, p.y], [s.x, 0, s.y], [s.x, hs, s.y], [p.x, 0, p.y], [s.x, hs, s.y], [p.x, hp, p.y]];
        if (sign2 > 0) for (let k = 0; k < pts.length; k += 3) [pts[k + 1], pts[k + 2]] = [pts[k + 2], pts[k + 1]];
        emit(pts, glass ? "glass" : "brick");
      }
      if (glass) {
        const count = Math.max(1, Math.round(length / 1.3));
        for (let j = 0; j <= count; j++) {
          const p = point(j / count, 0.055);
          b.box(p.x, 0, p.y, 0.065, roofAt(p), 0.09, "stone", angle);
        }
        const m3 = point(0.5, 0.055);
        b.box(m3.x, 0.12, m3.y, length, 0.1, 0.09, "stone", angle);
        continue;
      }
      const m2 = point(0.5, 0.035), eave = Math.min(roofAt(a), roofAt(q));
      for (const y of [0.17, 0.65, eave - 0.3, eave - 0.16]) b.box(m2.x, y, m2.y, length, 0.095, 0.07, y < 1 ? "ochre" : "brick", angle);
      for (let u = 0.06; u < 1; u += 0.3) {
        const p = point(u, 0.07);
        b.box(p.x, 0, p.y, 0.24, Math.min(roofAt(p), 3.8), 0.15, "brick", angle);
      }
      for (let u = 0.05; u < 1; u += 0.065) {
        const p = point(u, 0.1);
        b.box(p.x, eave - 0.42, p.y, 0.14, 0.17, 0.17, "brick", angle);
      }
    }
    const frontIndex = partIndex === 0 ? 9 : 3, f = facade2(frontIndex, partIndex === 0 ? 1 : 0), m = f.point(0.5, 0.14);
    b.box(m.x, 0.15, m.y, 3.25, 2.75, 0.13, partIndex === 0 ? "glass" : "green", f.angle);
    for (const u of [0.5 - 1.68 / f.length, 0.5 + 1.68 / f.length]) {
      const p = f.point(u, 0.19);
      b.box(p.x, 0.1, p.y, 0.14, 2.85, 0.13, "ochre", f.angle);
    }
    for (let j = 0; j < 20; j++) {
      const u = j / 19, x = (u - 0.5) * 3.7, y = 2.93 + 0.28 * (1 - (2 * u - 1) ** 2), p = f.point(0.5 + x / f.length, 0.2);
      b.box(p.x, y, p.y, 0.18, 0.28, 0.17, j % 3 === 0 ? "ochre" : "brick", f.angle);
    }
    const eye = f.point(0.5, 0.11), eyeY = 5.05;
    const disc2 = new T34.CircleGeometry(0.53, 24);
    b.add(disc2, "dark", eye.x, eyeY, eye.y, Math.atan2(f.n.x, f.n.y));
    const pc = (u, y) => {
      const p = f.point(0.5 + u / f.length, 0.18);
      return new T34.Vector3(p.x, y, p.y);
    };
    for (const [u, y, v, z] of [[0, eyeY + 0.36, 0.36, eyeY], [0.36, eyeY, 0, eyeY - 0.36], [0, eyeY - 0.36, -0.36, eyeY], [-0.36, eyeY, 0, eyeY + 0.36]]) beam(pc(u, y), pc(v, z), 0.065, "ochre");
    const crest = roofAt(f.point(0.5)), tip = f.point(0.5, 0.05);
    b.box(tip.x, crest - 0.16, tip.y, 0.68, 0.76, 0.36, "brick", f.angle);
    b.box(tip.x, crest + 0.6, tip.y, 0.83, 0.09, 0.47, "stone", f.angle);
    const half = f.length / 2, steps = 5, inset = 0.55;
    for (const side of [-1, 1]) for (let j = 0; j < steps; j++) {
      const x0 = side * (half - inset - j * (half - inset - 0.25) / steps), x1 = side * (half - inset - (j + 1) * (half - inset - 0.25) / steps);
      const lower = roofAt(f.point(0.5 + x0 / f.length)) - 0.48, upper = roofAt(f.point(0.5 + x1 / f.length)) - 0.48;
      const shelf = f.point(0.5 + (x0 + x1) / 2 / f.length, 0.16), riser = f.point(0.5 + x1 / f.length, 0.16);
      b.box(shelf.x, lower, shelf.y, Math.abs(x1 - x0) + 0.12, 0.15, 0.25, "brick", f.angle);
      b.box(riser.x, lower, riser.y, 0.14, Math.max(0.15, upper - lower + 0.15), 0.25, "brick", f.angle);
    }
  }
}

