// scripts/landmarks/beta-boulders-builder.ts
function buildBetaBoulders(_w, _d, b) {
  const makeShape = (rings) => {
    const s = new T35.Shape(rings[0].map((p) => new T35.Vector2(p[0], p[1])));
    for (const r of rings.slice(1)) s.holes.push(new T35.Path(r.map((p) => new T35.Vector2(p[0], p[1]))));
    return s;
  };
  const footprint = makeShape(beta_boulders_footprints_default.outline);
  b.add(openTopPrism(footprint, 0, 15.03), "white");
  const base = beta_boulders_footprints_default.roofs.find((r) => r.index === 177);
  b.add(upwardRoofPlane(makeShape(base.rings), 15.06), "slate");
  for (const roof of beta_boulders_footprints_default.roofs.filter((r) => [166, 168, 179].includes(r.index))) {
    const ring2 = roof.rings[0], cx2 = ring2.reduce((s, p2) => s + p2[0], 0) / ring2.length, cz = ring2.reduce((s, p2) => s + p2[1], 0) / ring2.length, cy = ring2.reduce((s, p2) => s + p2[2], 0) / ring2.length;
    let xx = 0, xz = 0, zz = 0, xy = 0, zy = 0;
    for (const p2 of ring2) {
      const x = p2[0] - cx2, z = p2[1] - cz, y = p2[2] - cy;
      xx += x * x;
      xz += x * z;
      zz += z * z;
      xy += x * y;
      zy += z * y;
    }
    const det = xx * zz - xz * xz, a = (xy * zz - zy * xz) / det, d = (zy * xx - xy * xz) / det;
    const height = (x, z) => cy + a * (x - cx2) + d * (z - cz), top = upwardRoofPlane(makeShape(roof.rings)), p = top.getAttribute("position");
    for (let i = 0; i < p.count; i++) p.setY(i, height(p.getX(i), p.getZ(i)));
    top.computeVertexNormals();
    top.userData.roofAssembly = roof.index;
    b.add(top, "slate");
    const values = [];
    for (const r of roof.rings) for (let i = 0; i < r.length; i++) {
      const p2 = r[i], q = r[(i + 1) % r.length];
      values.push(p2[0], 15.03, p2[1], q[0], 15.03, q[1], q[0], height(q[0], q[1]), q[1], p2[0], 15.03, p2[1], q[0], height(q[0], q[1]), q[1], p2[0], height(p2[0], p2[1]), p2[1]);
    }
    const wall = new T35.BufferGeometry();
    wall.setAttribute("position", new T35.Float32BufferAttribute(values, 3));
    wall.computeVertexNormals();
    b.add(wall, "dark");
  }
  for (const ring2 of base.rings.slice(1)) b.add(upwardRoofPlane(makeShape([ring2]), 15.02), "glass");
  function panel(p, q, y, h, c, offset = 0.12) {
    const tangent = q.clone().sub(p).normalize(), normal = new T35.Vector2(-tangent.y, tangent.x), mid = p.clone().add(q).multiplyScalar(0.5).addScaledVector(normal, offset);
    b.add(new T35.PlaneGeometry(p.distanceTo(q), h), c, mid.x, y + h / 2, mid.y, Math.atan2(-tangent.y, tangent.x));
  }
  function portalSolid(p, q, y, h) {
    const t = q.clone().sub(p).normalize(), n = new T35.Vector2(-t.y, t.x), m = p.clone().add(q).multiplyScalar(0.5).addScaledVector(n, 0.4);
    b.box(m.x, y, m.y, p.distanceTo(q), h, 0.6, "dark", Math.atan2(-t.y, t.x));
  }
  function ribbon(p, q, y, h, c = "white", offset = 0.12) {
    panel(p, q, y - 0.13, h + 0.26, c, offset);
    panel(p, q, y, h, "glass", offset + 0.045);
    const l = p.distanceTo(q), n = Math.ceil(l / 1.9);
    for (let i = 0; i <= n; i++) {
      const t = q.clone().sub(p).normalize(), normal = new T35.Vector2(-t.y, t.x), m = p.clone().lerp(q, i / n).addScaledVector(normal, offset + 0.08);
      b.box(m.x, y, m.y, 0.075, h, 0.075, "frame");
    }
    panel(p, q, y + h * 0.48, 0.07, "frame", offset + 0.085);
  }
  const ring = beta_boulders_footprints_default.facadePerimeter;
  const se = new T35.Vector2(...ring[1]), ne = new T35.Vector2(...ring[30]), frontAxis = ne.clone().sub(se), frontLength = frontAxis.length();
  frontAxis.normalize();
  const frontageFraction = (p) => p.clone().sub(se).dot(frontAxis) / frontLength;
  function frontageClip(p, q, lo, hi) {
    const a = frontageFraction(p), d = frontageFraction(q) - a;
    if (Math.abs(d) < 1e-5) return void 0;
    const f = (lo - a) / d, g = (hi - a) / d, begin = Math.max(0, Math.min(f, g)), end = Math.min(1, Math.max(f, g));
    if (end <= begin) return void 0;
    return [p.clone().lerp(q, begin), p.clone().lerp(q, end)];
  }
  for (let i = 0; i < ring.length - 1; i++) {
    const p = new T35.Vector2(...ring[i]), q = new T35.Vector2(...ring[i + 1]);
    if (p.distanceTo(q) < 0.3) continue;
    const principal = i >= 1 && i < 30;
    const length = p.distanceTo(q), front = q.y - p.y < -2 || q.x - p.x > 2;
    for (const [y, h] of [[6.05, 3.85], [11.05, 3.25]]) {
      if (principal) {
        for (const [lo, hi] of [[0.015, 0.38], [0.46, 0.985]]) {
          const clipped = frontageClip(p, q, lo, hi);
          if (clipped && clipped[0].distanceTo(clipped[1]) > 0.3) ribbon(clipped[0], clipped[1], y, h);
        }
      } else {
        const count = Math.max(1, Math.round(length / 13));
        for (let k = 0; k < count; k++) {
          const pa = p.clone().lerp(q, (k + 0.035) / count), pb = p.clone().lerp(q, (k + 0.91) / count);
          ribbon(pa, pb, y, h);
        }
      }
    }
    if (principal) {
      for (const [lo, hi] of [[0.026, 0.366], [0.39, 0.985]]) {
        const c = frontageClip(p, q, lo, hi);
        if (c && c[0].distanceTo(c[1]) > 0.3) ribbon(c[0], c[1], 0.45, 3.85, "concrete", 0.12);
      }
      const portal = frontageClip(p, q, 0.01, 0.39);
      if (portal) portalSolid(portal[0], portal[1], 4.3, 0.92);
      for (const [lo, hi] of [[0.01, 0.026], [0.366, 0.39]]) {
        const c = frontageClip(p, q, lo, hi);
        if (c) portalSolid(c[0], c[1], 0.08, 4.65);
      }
      const door = frontageClip(p, q, 0.17, 0.225);
      if (door) {
        ribbon(door[0], door[1], 0.18, 3.5, "dark", 0.21);
        panel(door[0], door[1], 3.72, 0.14, "dark", 0.31);
      }
    } else if (front) ribbon(p.clone().lerp(q, 0.018), q.clone().lerp(p, 0.018), 0.45, 4.1, "concrete");
    else ribbon(p.clone().lerp(q, 0.04), q.clone().lerp(p, 0.04), 1.1, 2.6, "concrete");
    panel(p, q, 5.22, 0.28, "white", 0.18);
    panel(p, q, 10.25, 0.65, "white", 0.18);
    panel(p, q, 14.55, 0.5, "white", 0.18);
    panel(p, q, 15.18, 0.075, "dark", 0.2);
    panel(p, q, 15.57, 0.06, "dark", 0.2);
    for (let k = 0; k <= Math.ceil(length / 3); k++) {
      const t = q.clone().sub(p).normalize(), n = new T35.Vector2(-t.y, t.x), m = p.clone().lerp(q, k / Math.ceil(length / 3)).addScaledVector(n, 0.2);
      b.box(m.x, 15.1, m.y, 0.05, 0.53, 0.05, "dark");
    }
  }
  for (const roof of beta_boulders_footprints_default.roofs.filter((r) => [168, 179].includes(r.index))) for (const ring2 of roof.rings) {
    for (let i = 0; i < ring2.length; i++) {
      const p = new T35.Vector2(ring2[i][0], ring2[i][1]), q = new T35.Vector2(ring2[(i + 1) % ring2.length][0], ring2[(i + 1) % ring2.length][1]);
      if (p.distanceTo(q) > 4) ribbon(p.clone().lerp(q, 0.04), q.clone().lerp(p, 0.04), 15.4, 2.65, "dark", 0.14);
    }
  }
}

