        const m = (l + r) / 2;
        const geo = new T42.PlaneGeometry(r - l, h);
        const angle = Math.atan2(outward.x, outward.y);
        add2(geo, c, a[0] + tangent.x * m + outward.x * offset, y + h / 2, a[2] + tangent.y * m + outward.y * offset, angle);
