import * as T45 from "three";
function buildRemEiland(w, d, b) {
  const { add: add2, box: box2, sign: sign2 } = b;
  function strut(a, c, r, colour) {
    const delta = c.clone().sub(a), g = new T45.CylinderGeometry(r, r, delta.length(), 6);
    g.applyQuaternion(new T45.Quaternion().setFromUnitVectors(new T45.Vector3(0, 1, 0), delta.normalize()));
    const mid = a.clone().add(c).multiplyScalar(0.5);
    add2(g, colour, mid.x, mid.y, mid.z);
  }
  let width = w * 0.95, depth = d * 0.93;
  for (let x of [-width * 0.4, width * 0.4]) for (let z of [-depth * 0.4, depth * 0.4]) {
    box2(x, 0, z, 0.8, 12, 0.8, "red");
  }
  for (let z of [-depth * 0.4, depth * 0.4]) for (let s of [-1, 1]) strut(new T45.Vector3(-width * 0.4, s < 0 ? 1 : 11, z), new T45.Vector3(width * 0.4, s < 0 ? 11 : 1, z), 0.17, "red");
  box2(0, 12, 0, width, 1, depth, "white");
  box2(0, 13, 0, width * 0.89, 6.5, depth * 0.88, "red");
  for (let x = -width * 0.37; x < width * 0.4; x += 3) for (let z of [-depth * 0.447, depth * 0.447]) box2(x, 14.5, z, 2, 2.5, 0.15, "glass");
  box2(0, 19.5, 0, width + 1, 0.6, depth + 1, "white");
  const stairWidth = 1.6, nearX = (width + 1) / 2 + 0.9, farX = nearX + stairWidth;
  const nearZ = -depth * 0.36, farZ = depth * 0.36;
  for (const z of [-(depth + 1) / 2, (depth + 1) / 2]) {
    box2(0, 21.1, z, width + 1, 0.1, 0.12, "frame");
    for (let x = -(width + 1) / 2; x <= (width + 1) / 2; x += 3) box2(x, 20.1, z, 0.12, 1, 0.12, "frame");
  }
  box2(-(width + 1) / 2, 21.1, 0, 0.12, 0.1, depth + 1, "frame");
  for (let z = -(depth + 1) / 2; z <= (depth + 1) / 2; z += 2) box2(-(width + 1) / 2, 20.1, z, 0.12, 1, 0.12, "frame");
  const edgeX = (width + 1) / 2, gapStart = farZ - 1, gapEnd = farZ + 1;
  for (const [start, end] of [[-(depth + 1) / 2, gapStart], [gapEnd, (depth + 1) / 2]]) if (end > start) {
    box2(edgeX, 21.1, (start + end) / 2, 0.12, 0.1, end - start, "frame");
    for (let z = start; z <= end; z += 2) box2(edgeX, 20.1, z, 0.12, 1, 0.12, "frame");
  }
  box2(width * 0.3, 20, 0, 4, 4.6, depth * 0.6, "red");
  box2(width * 0.3, 24.6, 0, 4.5, 0.6, depth * 0.7, "white");
  box2(width * 0.3, 25.2, 0, 0.25, 9, 0.25, "frame");
  add2(new T45.CylinderGeometry(depth * 0.58, depth * 0.58, 0.35, 16), "slate", -width * 0.1, 20.5, 0);
  for (const x of [-width * 0.1 - 0.9, -width * 0.1 + 0.9]) box2(x, 20.68, 0, 0.35, 0.025, 3, "white");
  box2(-width * 0.1, 20.68, 0, 2.15, 0.025, 0.35, "white");
  sign2("REM", 0, 17.5, depth * 0.45, 0.17);
  function stairFlight(x, z0, z1, y0, y1) {
    const count = Math.ceil((y1 - y0) / 0.24), run = (z1 - z0) / count, rise = (y1 - y0) / count;
    for (let j = 0; j < count; j++) box2(x, y0 + (j + 1) * rise - 0.1, z0 + (j + 0.5) * run, stairWidth, 0.1, Math.abs(run) + 0.025, "frame");
    for (const side of [-1, 1]) {
      const sx = x + side * (stairWidth / 2 - 0.07);
      strut(new T45.Vector3(sx, y0 - 0.08, z0), new T45.Vector3(sx, y1 - 0.08, z1), 0.07, "frame");
      strut(new T45.Vector3(sx, y0 + 1, z0), new T45.Vector3(sx, y1 + 1, z1), 0.045, "frame");
      for (let j = 0; j <= count; j += 3) box2(sx, y0 + j * rise, z0 + j * run, 0.07, 1, 0.07, "frame");
    }
  }
  function stairLanding(y, z, connectDeck = false) {
    const left = connectDeck ? width * (y < 15 ? 0.46 : 0.43) : nearX - stairWidth / 2, right = farX + stairWidth / 2;
    box2((left + right) / 2, y - 0.12, z, right - left, 0.12, 2, "frame");
    const outerZ = z + (z > 0 ? 1 : -1);
    box2((left + right) / 2, y + 1, outerZ, right - left, 0.08, 0.08, "frame");
    for (let x = left; x <= right; x += 1) box2(x, y, outerZ, 0.07, 1, 0.07, "frame");
    box2(right, y + 1, z, 0.08, 0.08, 2, "frame");
    box2(right, y, z, 0.07, 1, 0.07, "frame");
  }
  const approachX = nearX - stairWidth / 2 - 0.6, bridgeStart = -width / 2, bridgeZ = 0, approachZ = nearZ - 0.65;
  box2((bridgeStart + approachX) / 2, 0.88, bridgeZ, approachX - bridgeStart, 0.12, 1.2, "frame");
  box2(approachX, 0.88, approachZ / 2, 1.2, 0.12, -approachZ + 1.2, "frame");
  box2(approachX + 0.6, 0.88, approachZ, 1.2, 0.12, 1.2, "frame");
  for (const side of [-1, 1]) {
    const railEnd = approachX + (side > 0 ? 0.6 : -0.6);
    box2((bridgeStart + railEnd) / 2, 2, bridgeZ + side * 0.6, railEnd - bridgeStart, 0.08, 0.08, "frame");
    for (let x = bridgeStart; x <= approachX - 0.6; x += 2) box2(x, 1, bridgeZ + side * 0.6, 0.07, 1, 0.07, "frame");
  }
  box2(approachX - 0.6, 2, approachZ / 2, 0.08, 0.08, -approachZ, "frame");
  for (let z = approachZ; z <= 0; z += 1.5) box2(approachX - 0.6, 1, z, 0.07, 1, 0.07, "frame");
  box2(approachX, 2, approachZ - 0.6, 1.2, 0.08, 0.08, "frame");
  stairLanding(1, nearZ);
  stairFlight(nearX, nearZ, farZ, 1, 5);
  stairLanding(5, farZ);
  stairFlight(farX, farZ, nearZ, 5, 9);
  stairLanding(9, nearZ);
  stairFlight(nearX, nearZ, farZ, 9, 13);
  stairLanding(13, farZ, true);
  stairFlight(farX, farZ, nearZ, 13, 16.55);
  stairLanding(16.55, nearZ);
  stairFlight(nearX, nearZ, farZ, 16.55, 20.1);
  stairLanding(20.1, farZ, true);
}

