            const foyer = part.osmId === "w751573304", h = foyer && y < 6 ? Math.min(4.8, top - y - 1) : 1.9, w = Math.min(foyer ? length / count * 0.77 : 2, length / count * 0.74), paneX = xx + nx * 0.16, paneZ = zz + nz * 0.16;
            box2(paneX, y, paneZ, w, h, 0.13, "glass", a);
