// scripts/landmarks/theater-builders.ts
import * as T63 from "three";
function buildTheaterLandmark(id, w, d, b) {
  const width = d, depth = w, front = depth / 2;
  function add2(g, c, x = 0, y = 0, z = 0) {
    g.translate(x, y, z);
    g.rotateY(Math.PI / 2);
    b.add(g, c);
  }
  function box2(x, y, z, a, h, c, colour) {
    add2(new T63.BoxGeometry(a, h, c), colour, x, y + h / 2, z);
  }
  function gable(x, y, z, a, h, c, colour) {
    const s = new T63.Shape();
    s.moveTo(-a / 2, 0);
    s.lineTo(a / 2, 0);
    s.lineTo(0, h);
    s.closePath();
    add2(new T63.ExtrudeGeometry(s, { depth: c, bevelEnabled: false }), colour, x, y, z - c / 2);
  }
  function arch3(x, y, z, a, h, colour) {
    const s = new T63.Shape();
    s.moveTo(-a / 2, 0);
    s.lineTo(a / 2, 0);
    s.lineTo(a / 2, h - a / 2);
    s.absarc(0, h - a / 2, a / 2, 0, Math.PI, false);
    s.closePath();
    add2(new T63.ExtrudeGeometry(s, { depth: 0.14, bevelEnabled: false, curveSegments: 6 }), colour, x, y, z);
  }
  function win(x, y, z, a, h, arched = false) {
    if (arched) {
      arch3(x, y - 0.12, z, a + 0.35, h + 0.25, "stone");
      arch3(x, y, z + 0.15, a, h, "dark");
    } else {
      box2(x, y - 0.12, z, a + 0.35, h + 0.24, 0.15, "stone");
      box2(x, y, z + 0.12, a, h, 0.13, "dark");
    }
    box2(x, y, z + 0.3, 0.1, h, 0.07, "stone");
    box2(x, y + h * 0.55, z + 0.3, a, 0.1, 0.07, "stone");
    box2(x, y - 0.18, z, a + 0.5, 0.15, 0.4, "stone");
  }
  function cylinder(x, y, z, r, h, c) {
    add2(new T63.CylinderGeometry(r, r, h, 12), c, x, y + h / 2, z);
  }
  function text(t, x, y, z, p, c) {
    const letters3 = { A: ["010", "101", "111", "101", "101"], B: ["110", "101", "110", "101", "110"], D: ["110", "101", "101", "101", "110"], E: ["111", "100", "110", "100", "111"], F: ["111", "100", "110", "100", "100"], I: ["111", "010", "010", "010", "111"], K: ["101", "110", "100", "110", "101"], L: ["100", "100", "100", "100", "111"], M: ["10001", "11011", "10101", "10001", "10001"], N: ["1001", "1101", "1011", "1001", "1001"], O: ["111", "101", "101", "101", "111"], R: ["110", "101", "110", "101", "101"], S: ["111", "100", "111", "001", "111"], T: ["111", "010", "010", "010", "010"], X: ["101", "101", "010", "101", "101"] };
    let total = [...t].reduce((v, ch) => v + (letters3[ch]?.[0].length ?? 2) + 1, 0) * p, u = x - total / 2;
    for (const ch of t) {
      const rows = letters3[ch];
      if (rows) {
        for (let j = 0; j < 5; j++) for (let k = 0; k < rows[j].length; k++) if (rows[j][k] === "1") box2(u + k * p, y + (4 - j) * p, z, p * 0.85, p * 0.85, 0.08, c);
      }
      u += ((rows?.[0].length ?? 2) + 1) * p;
    }
  }
  if (id === "felix-meritis") {
    const fd = Math.min(31, depth * 0.4), fz = front - fd / 2;
    box2(0, 0, fz, width * 0.96, 23, fd, "brick");
    box2(0, 23, fz, width * 0.98, 0.5, fd, "slate");
    box2(0, 0, -depth * 0.07, width * 0.53, 19, depth * 0.36, "brick");
    box2(0, 19, -depth * 0.07, width * 0.56, 0.4, depth * 0.36, "slate");
    let hall = new T63.CylinderGeometry(1, 1, 19, 24);
    hall.scale(width * 0.45, 1, depth * 0.21);
    add2(hall, "brick", 0, 9.5, -depth * 0.29);
    let roof = new T63.CylinderGeometry(1, 1, 0.5, 24);
    roof.scale(width * 0.46, 1, depth * 0.21);
    add2(roof, "slate", 0, 19.3, -depth * 0.29);
    const z = front + 0.06;
    box2(0, 0, z, width, 23, 0.4, "stone");
    for (const y of [0.2, 5.8, 21.7, 23]) box2(0, y, z + 0.3, width + 0.5, 0.4, 0.6, "white");
    for (let i = 0; i < 5; i++) {
      let x = (i - 2) * width * 0.185;
      win(x, 0.8, z + 0.26, width * 0.14, 4.1);
      win(x, 6.5, z + 0.26, width * 0.14, 7, true);
      win(x, 16, z + 0.26, width * 0.14, 3.3);
    }
    for (const x of [-width * 0.29, -width * 0.1, width * 0.1, width * 0.29]) {
      cylinder(x, 5.8, z + 0.58, 0.45, 15.8, "stone");
      box2(x, 5.7, z + 0.58, 1.25, 0.35, 1.25, "white");
      box2(x, 21.1, z + 0.58, 1.35, 0.6, 1.35, "white");
    }
    gable(0, 23.3, z + 0.3, width + 1, 4.1, 1.2, "stone");
    gable(0, 23.6, z + 0.96, width - 1, 3.3, 0.16, "white");
    text("FELIX MERITIS", 0, 22, z + 0.95, 0.17, "dark");
    box2(0, 23.5, front - fd * 0.66, width * 0.58, 0.5, fd * 0.32, "stone");
    cylinder(0, 24, front - fd * 0.66, 3.2, 3.5, "stone");
    add2(new T63.ConeGeometry(3.5, 2.1, 8), "slate", 0, 28.55, front - fd * 0.66);
    for (let i = 0; i < 8; i++) {
      let a = i * Math.PI / 4;
      box2(3.15 * Math.sin(a), 24.8, front - fd * 0.66 + 3.15 * Math.cos(a), 0.7, 1.7, 0.12, "dark");
    }
  } else if (id === "kleine-komedie") {
    box2(0, 0, 0, width * 0.98, 13.5, depth * 0.97, "brick");
    gable(0, 13.5, 0, width * 0.98, 5, depth * 0.97, "slate");
    const z = front + 0.06;
    for (const y of [0.1, 5.1, 9.3, 13.3]) box2(0, y, z, width, 0.25, 0.4, "stone");
    for (let i = 0; i < 6; i++) {
      let x = (i - 2.5) * width * 0.15;
      win(x, 0.5, z, 2.1, 3.8, true);
      win(x, 5.6, z, 2.05, 3);
      win(x, 9.8, z, 2.05, 2.5);
    }
    box2(0, 13.6, z, width + 0.4, 0.35, 0.7, "white");
    text("KLEINE KOMEDIE", 0, 4.3, z + 0.45, 0.22, "red");
    for (const x of [-width * 0.29, 0, width * 0.29]) {
      box2(x, 3.4, z + 0.5, 2.8, 0.15, 1.6, "glass");
      box2(x, 3.5, z + 0.5, 2.9, 0.09, 1.7, "frame");
    }
  } else if (id === "de-balie") {
    box2(0, 0, 0, width * 0.97, 10.8, depth * 0.96, "brick");
    gable(0, 10.8, 0, width * 0.97, 5.1, depth * 0.96, "slate");
    const z = front + 0.05;
    for (const y of [0.15, 4.8, 10.5]) box2(0, y, z, width, 0.25, 0.4, "stone");
    for (let i = 0; i < 8; i++) {
      const x = (i - 3.5) * width * 0.118;
      win(x, 0.7, z, 2.4, 3.7, true);
      win(x, 5.6, z, 2.35, 4.05, true);
    }
    for (const x of [-width * 0.34, width * 0.34]) {
      gable(x, 10.7, z, 8.2, 5.4, 0.8, "brick");
      gable(x, 11, z + 0.45, 7.3, 4.8, 0.2, "stone");
      gable(x, 11.35, z + 0.55, 6.4, 4.2, 0.2, "brick");
      win(x, 11.3, z + 0.7, 1.7, 2.5, true);
      box2(x, 16, z, 0.25, 1, 0.25, "stone");
    }
    box2(0, 0, z + 0.25, 4.6, 5.2, 0.6, "stone");
    arch3(0, 0.2, z + 0.61, 3.4, 4.4, "dark");
    box2(0, 4.9, z + 0.2, 5.4, 0.3, 0.9, "stone");
    text("DE BALIE", 0, 5.3, z + 0.65, 0.25, "white");
    for (const x of [-4.7, 4.7]) box2(x, 3, z + 0.3, 1.2, 5.3, 0.12, "gold");
  } else throw new Error(`No theatre builder for ${id}`);
}

// scripts/landmarks/house-museum-builders.ts
import * as T64 from "three";
function buildHouseMuseumLandmark(id, w, d, b) {
  const { box: box2, add: add2, prism: prism2, hip: hip2, sign: sign2, window: window2 } = b;
  function sash(x, y, z, width, height, c = "white") {
    box2(x, y - 0.12, z, width + 0.27, height + 0.25, 0.2, c);
    box2(x, y, z + 0.13, width, height, 0.12, "glass");
    for (let u of [-width / 4, 0, width / 4]) box2(x + u, y, z + 0.23, 0.065, height, 0.07, c);
    for (let v of [height * 0.33, height * 0.66]) box2(x, y + v, z + 0.24, width, 0.065, 0.08, c);
  }
  function stairs(x, z, width, height) {
    for (let i = 0; i < 5; i++) box2(x, i * height / 5, z + (4 - i) * 0.38, width, height / 5, 0.44, "stone");
  }
  function statue(x, y, z) {
    box2(x, y, z, 0.7, 0.4, 0.7, "stone");
    add2(new T64.CylinderGeometry(0.2, 0.33, 1.35, 6), "stone", x, y + 1.03, z);
    add2(new T64.IcosahedronGeometry(0.22, 0), "stone", x, y + 1.92, z);
    box2(x - 0.3, y + 0.95, z, 0.18, 0.8, 0.22, "stone", 0.25);
    box2(x + 0.3, y + 1.2, z, 0.18, 0.6, 0.22, "stone", -0.4);
  }
  if (id === "anne-frank-house") {
    const frontDepth = d * 0.57, frontZ = d * 0.215, backDepth = d * 0.28, backZ = -d * 0.36;
    box2(0, 0, frontZ, w, 14.4, frontDepth, "brick");
    box2(0, 14.4, frontZ, w + 0.05, 0.5, frontDepth + 0.08, "white");
    prism2(0, 14.9, frontZ, w, frontDepth, 3, "red");
    box2(0, 13.9, d / 2 - 0.16, w, 2.2, 0.35, "brick");
    box2(0, 16.1, d / 2, w + 0.12, 0.32, 0.5, "white");
    box2(0, 0, backZ, w * 0.96, 11.8, backDepth, "brick");
    prism2(0, 11.8, backZ, w * 0.98, backDepth, 3.6, "red");
    box2(-w * 0.39, 0, -d * 0.04, w * 0.22, 10.5, d * 0.18, "brick");
    box2(-w * 0.39, 10.5, -d * 0.04, w * 0.24, 0.25, d * 0.18, "slate");
    for (let x of [-w * 0.31, 0, w * 0.31]) {
      for (let y of [4.4, 8, 11.5]) sash(x, y, d / 2 + 0.05, w * 0.2, 2.3);
      box2(x, 0, d / 2 + 0.04, w * 0.26, 3.5, 0.21, "dark");
      sash(x, 2.55, d / 2 + 0.16, w * 0.19, 0.6, "frame");
      box2(x, 1, d / 2 + 0.19, 0.045, 1.1, 0.11, "gold");
    }
    for (let y of [3.9, 7.5, 11.05]) for (let x of [-w * 0.43, w * 0.43]) {
      box2(x, y, d / 2 + 0.2, 0.07, 0.65, 0.1, "dark");
      box2(x, y + 0.3, d / 2 + 0.2, 0.27, 0.06, 0.1, "dark");
    }
    for (let x of [-w * 0.23, w * 0.23]) for (let y of [3.7, 7.1]) sash(x, y, -d / 2 - 0.1, w * 0.29, 2.2);
    box2(w * 0.31, 3.27, d / 2 + 0.28, w * 0.26, 0.19, 0.04, "white");
    box2(0, 15.8, d / 2 + 0.37, 0.15, 0.15, 0.95, "dark");
  } else if (id === "rembrandt-house") {
    box2(0, 0, 0, w, 17.4, d, "brick");
    prism2(0, 17.4, 0, w, d, 5.3, "slate");
    const front = d / 2 + 0.03;
    for (let y of [1.1, 3, 6.9, 11.5, 16.7, 17.3]) box2(0, y, front, w + 0.07, 0.25, 0.35, "stone");
    for (let x of [-w * 0.47, w * 0.47]) {
      box2(x, 0, front, 0.44, 17.5, 0.5, "stone");
      for (let y = 1; y < 17; y += 1.05) box2(x, y, front + 0.1, 0.6, 0.25, 0.35, "stone");
    }
    for (let x of [-w * 0.35, -w * 0.12, w * 0.12, w * 0.35]) {
      for (let y of [7.3, 12.05]) window2(x, y, front + 0.09, w * 0.14, 3.8);
      for (const [y, h] of [[3.6, 3.3], [8.3, 2.8], [13.3, 2.5]]) {
        sash(x, y, front + 0.25, w * 0.135, h);
        for (let side of [-1, 1]) box2(x + side * w * 0.105, y, front + 0.5, w * 0.065, h * 0.64, 0.16, "red", side * 0.27);
      }
    }
    prism2(0, 17.65, front + 0.13, w * 0.78, 0.55, 3.2, "stone");
    prism2(0, 17.9, front + 0.44, w * 0.65, 0.12, 2.45, "brick");
    for (let x of [-w * 0.37, w * 0.37]) {
      box2(x, 17.4, d * 0.23, w * 0.16, 3.1, d * 0.15, "stone");
      sash(x, 17.6, d * 0.31, w * 0.09, 2);
      prism2(x, 20.5, d * 0.23, w * 0.19, d * 0.16, 0.65, "stone");
    }
    for (let x of [-w * 0.23, w * 0.23]) {
      box2(x, 20.3, -d * 0.1, 0.95, 3.9, 1.05, "brick");
      box2(x, 24.2, -d * 0.1, 1.25, 0.3, 1.35, "dark");
    }
    stairs(0, front + 0.3, w * 0.19, 1.3);
    window2(0, 1.3, front + 0.4, w * 0.14, 4.3);
    prism2(0, 5.7, front + 0.45, w * 0.29, 0.45, 1.2, "stone");
  } else if (id === "moco-museum") {
    box2(0, 0, 0, w * 0.97, 2.4, d * 0.94, "stone");
    box2(0, 2.4, 0, w * 0.97, 9, d * 0.94, "brick");
    box2(0, 11.4, 0, w * 0.99, 2.7, d * 0.96, "white");
    hip2(0, 14.1, 0, w, d, 5.5, "slate");
    const front = d * 0.485;
    for (let side of [-1, 1]) {
      const z = side * front;
      for (let x = -w * 0.45; x <= w * 0.45; x += 2.05) box2(x, 11.4, z, 0.14, 2.7, 0.18, "brick");
      for (let y of [11.4, 12.6, 14]) box2(0, y, z, w, 0.14, 0.18, "brick");
      for (let x of [-w * 0.36, -w * 0.12, w * 0.12, w * 0.36]) for (let y of [3.4, 7.5, 11.8]) sash(x, y, z + 0.09, 1.55, y === 11.8 ? 1.8 : 2.6);
    }
    const bay = w * 0.15, bx = w * 0.2;
    box2(bx, 2.4, front + 0.6, bay, 8.9, 1.7, "stone");
    for (let y of [3.3, 7.5]) {
      sash(bx, y, front + 1.5, bay * 0.63, 2.9);
      for (let side of [-1, 1]) box2(bx + side * bay * 0.43, y, front + 0.6, 0.16, 2.9, 1.05, "glass");
    }
    box2(bx, 11.4, front + 0.6, w * 0.32, 2.7, 2, "white");
    prism2(bx, 14.1, front + 0.6, w * 0.33, 3.4, 4, "slate");
    prism2(bx, 14.1, front + 2.35, w * 0.33, 0.18, 4, "white");
    for (let u of [-1.25, 0, 1.25]) sash(bx + u, 11.75, front + 1.75, 0.95, 1.95);
    for (let x of [bx - w * 0.15, bx, bx + w * 0.15]) box2(x, 11.4, front + 2.5, 0.18, x === bx ? 6.7 : 2.7, 0.2, "brick");
    box2(bx, 14.1, front + 2.5, w * 0.33, 0.2, 0.2, "brick");
    const r = w * 0.16, h = 4;
    for (let side of [-1, 1]) {
      const g = new T64.BoxGeometry(Math.hypot(r, h), 0.19, 0.2);
      g.rotateZ(-side * Math.atan2(h, r));
      add2(g, "brick", bx + side * r / 2, 14.1 + h / 2, front + 2.5);
    }
    for (let x of [-w * 0.32, w * 0.37]) {
      box2(x, 12, 0, 1.15, 10.6, 1.15, "brick");
      box2(x, 22.6, 0, 1.45, 0.3, 1.45, "stone");
    }
    add2(new T64.CylinderGeometry(1.32, 1.32, 0.35, 16).rotateX(Math.PI / 2), "brick", -w * 0.17, 17.1, front * 0.42);
    add2(new T64.CylinderGeometry(1.08, 1.08, 0.38, 16).rotateX(Math.PI / 2), "glass", -w * 0.17, 17.1, front * 0.42 + 0.16);
    for (let u of [-0.5, 0, 0.5]) box2(-w * 0.17 + u, 16.05, front * 0.42 + 0.39, 0.08, 2.1, 0.1, "white");
    box2(-w * 0.17, 17.1, front * 0.42 + 0.39, 2.1, 0.08, 0.1, "white");
    stairs(bx, front + 1.65, 2.5, 2.4);
    window2(bx, 2.4, front + 1.6, 1.4, 3.3);
  } else if (id === "museum-van-loon") {
    box2(0, 0, 0, w, 14.7, d, "brick");
    box2(0, 0, d / 2 - 0.1, w, 14.7, 0.4, "stone");
    hip2(0, 14.7, 0, w, d, 3.7, "slate");
    const front = d / 2 + 0.12;
    for (let x of [-w * 0.36, -w * 0.18, 0, w * 0.18, w * 0.36]) {
      for (let y of [3.3, 7.5, 11.3]) sash(x, y, front, 1.35, 2.55, "stone");
      box2(x, 14.5, front, 0.35, 1, 0.55, "stone");
    }
    for (let x of [-w * 0.39, -w * 0.13, w * 0.13, w * 0.39]) statue(x, 15.5, front);
    for (let y of [2.4, 6.6, 10.5, 14.1, 15.3]) box2(0, y, front, w + 0.05, 0.23, 0.45, "stone");
    stairs(0, front + 0.3, 2.5, 1.6);
    window2(0, 1.6, front + 0.23, 1.8, 4.1);
    box2(0, 6.1, front + 0.7, 2.8, 0.2, 1.4, "stone");
    for (let x of [-1.3, 1.3]) box2(x, 6.3, front + 1.3, 0.12, 0.9, 0.12, "dark");
    box2(0, 7.2, front + 1.3, 2.8, 0.1, 0.1, "dark");
    for (let x of [-w * 0.26, w * 0.26]) {
      box2(x, 15.7, 0, 1.1, 3.2, 1.1, "brick");
      box2(x, 18.9, 0, 1.4, 0.3, 1.4, "stone");
    }
    box2(0, 0, -d / 2 - 0.1, w, 9.6, 0.35, "white");
    for (let x of [-w * 0.28, w * 0.28]) {
      box2(x, 2.2, -d / 2 - 0.35, 1.6, 3.9, 0.13, "blue");
      statue(x, 2.35, -d / 2 - 0.48);
    }
    for (let x of [-w * 0.16, w * 0.16]) box2(x, 1.5, -d / 2 - 0.35, 0.35, 6, 0.45, "stone");
    prism2(0, 7.5, -d / 2 - 0.2, w * 0.45, 0.6, 1.7, "stone");
    box2(0, 1.5, -d / 2 - 0.4, 1.8, 4.6, 0.13, "dark");
  } else throw Error(`Unknown house museum ${id}`);
}

// scripts/landmarks/civic-builders.ts
import * as T65 from "three";
function buildCivicLandmark(id, w, d, b) {
  const { add: add2, box: box2, sign: sign2 } = b;
  function hipped(x, y, z, a, c, h, topX, topZ, colour) {
    const v = [[-a / 2, 0, -c / 2], [a / 2, 0, -c / 2], [a / 2, 0, c / 2], [-a / 2, 0, c / 2], [-topX / 2, h, -topZ / 2], [topX / 2, h, -topZ / 2], [topX / 2, h, topZ / 2], [-topX / 2, h, topZ / 2]];
    const f = [0, 4, 5, 0, 5, 1, 1, 5, 6, 1, 6, 2, 2, 6, 7, 2, 7, 3, 3, 7, 4, 3, 4, 0, 4, 7, 6, 4, 6, 5, 0, 1, 2, 0, 2, 3];
    const g = new T65.BufferGeometry();
    g.setAttribute("position", new T65.Float32BufferAttribute(f.flatMap((i) => v[i]), 3));
    g.computeVertexNormals();
    add2(g, colour, x, y, z);
  }
  function arched(x, y, z, a, h, colour, angle = 0) {
    let s = new T65.Shape();
    s.moveTo(-a / 2, 0);
    s.lineTo(a / 2, 0);
    s.lineTo(a / 2, h - a / 2);
    s.absarc(0, h - a / 2, a / 2, 0, Math.PI, false);
    s.closePath();
    add2(new T65.ExtrudeGeometry(s, { depth: 0.15, bevelEnabled: false, curveSegments: 7 }), colour, x, y, z, angle);
  }
  function multiWindow(x, y, z, a, h, angle = 0) {
    function piece(u, v, z1, ww, hh, dd, c) {
      const g = new T65.BoxGeometry(ww, hh, dd);
      g.translate(u, v + hh / 2, z1);
      add2(g, c, x, y, z, angle);
    }
    piece(0, -0.12, 0, a + 0.35, h + 0.24, 0.16, "white");
    piece(0, 0, 0.12, a, h, 0.13, "dark");
    for (let u = -a / 2 + a / 4; u < a / 2; u += a / 4) piece(u, 0, 0.23, 0.08, h, 0.09, "white");
    for (let v = h / 4; v < h; v += h / 4) piece(0, v, 0.23, a, 0.08, 0.09, "white");
  }
  function column(x, y, z, r, h) {
    add2(new T65.CylinderGeometry(r * 0.85, r, h, 12), "stone", x, y + h / 2, z);
    box2(x, y, z, r * 2.8, 0.3, r * 2.8, "stone");
    box2(x, y + h - 0.3, z, r * 2.8, 0.3, r * 2.8, "stone");
    for (const dx of [-r * 0.9, r * 0.9]) for (const dz of [-r * 0.9, r * 0.9]) add2(new T65.IcosahedronGeometry(r * 0.4, 0), "stone", x + dx, y + h - 0.05, z + dz);
  }
  function clock2(x, y, z, r, angle = 0) {
    const disc2 = new T65.CylinderGeometry(r, r, 0.16, 24).rotateX(Math.PI / 2);
    add2(disc2, "stone", x, y, z, angle);
    const face = new T65.CylinderGeometry(r * 0.81, r * 0.81, 0.2, 24).rotateX(Math.PI / 2);
    add2(face, "dark", x, y, z + 0.1, angle);
    for (let i = 0; i < 12; i++) {
      const a = i * Math.PI / 6;
      box2(x + Math.sin(a) * r * 0.67, y + Math.cos(a) * r * 0.67 - 0.055, z + 0.23, 0.065, 0.11, 0.06, "gold");
    }
    box2(x, y, z + 0.3, 0.07, r * 0.65, 0.07, "gold");
    box2(x, y - 0.03, z + 0.31, r * 0.52, 0.07, 0.07, "gold");
  }
  function curvedRoof(x, y, z, a, c, h) {
    const cols = 12, rows = 8, verts = [];
    function p(i, j) {
      const xx = -a / 2 + a * i / cols, zz = -c / 2 + c * j / rows, t = Math.abs(zz) / (c / 2), u = Math.abs(xx) / (a / 2);
      return [xx, h * (1 - t) ** 1.65 + u ** 4 * t * h * 0.32, zz];
    }
    for (let i = 0; i < cols; i++) for (let j = 0; j < rows; j++) {
      const q = [p(i, j), p(i + 1, j), p(i + 1, j + 1), p(i, j + 1)];
      verts.push(...q[0], ...q[1], ...q[2], ...q[0], ...q[2], ...q[3]);
    }
    const g = new T65.BufferGeometry();
    g.setAttribute("position", new T65.Float32BufferAttribute(verts, 3));
    g.computeVertexNormals();
    add2(g, "gold", x, y, z);
    box2(x, y + h, z, a * 0.96, 0.16, 0.18, "red");
    for (const side of [-1, 1]) for (let i = 0; i <= cols; i++) {
      const v = p(i, side < 0 ? 0 : rows);
      box2(x + v[0], y + v[1] - 0.18, z + v[2], 0.22, 0.28, 0.4, "red");
    }
    for (let u = -a / 2 + 0.3; u < a / 2; u += 0.65) box2(x + u, y - 0.42, z, 0.22, 0.35, c * 0.9, "red");
  }
  if (id === "amstelkerk") {
    const a = w * 0.97, c = d * 0.95;
    box2(0, 0, 0, a, 6.6, c, "white");
    hipped(0, 6.6, 0, a + 0.5, c + 0.5, 4.1, a * 0.59, c * 0.61, "slate");
    box2(0, 10.7, 0, a * 0.57, 3.3, c * 0.59, "white");
    hipped(0, 14, 0, a * 0.61, c * 0.63, 5.1, a * 0.19, c * 0.12, "slate");
    for (const side of [-1, 1]) {
      const z = side * c / 2;
      for (let y = 0.5; y < 6.6; y += 0.44) box2(0, y, z + 0.03 * side, a, 0.045, 0.045, "stone");
      for (let x = -a * 0.4; x < a * 0.42; x += 5.1) multiWindow(x, 1.3, z + side * 0.09, 2.65, 4.2, side > 0 ? 0 : Math.PI);
    }
    for (const side of [-1, 1]) {
      const x = side * a / 2;
      for (let y = 0.5; y < 6.6; y += 0.44) box2(x, y, 0, 0.045, 0.045, c, "stone");
      for (let z = -c * 0.35; z < c * 0.4; z += 5) multiWindow(x + side * 0.09, 1.3, z, 2.65, 4.2, side > 0 ? Math.PI / 2 : -Math.PI / 2);
    }
    for (const x of [-a * 0.18, a * 0.18]) {
      arched(x, 11.1, c * 0.3 + 0.03, 2.6, 2.5, "white");
      arched(x, 11.25, c * 0.3 + 0.2, 2.25, 2.2, "dark");
    }
    box2(0, 0, c / 2 - 1, 7.6, 6.9, 4.4, "brick");
    hipped(0, 6.9, c / 2 - 1, 8, 4.9, 4.5, 0.15, 0.15, "slate");
    for (const x of [-2.5, 0, 2.5]) multiWindow(x, 3.8, c / 2 + 1.28, 1.4, 2.3);
    box2(0, 0, c / 2 + 1.35, 2.7, 3.2, 0.25, "stone");
    box2(0, 0.1, c / 2 + 1.55, 2.1, 2.8, 0.15, "dark");
    sign2("AMSTELKERK", 0, 3.15, c / 2 + 1.6, 0.09, "gold");
    box2(0, 19.1, 0, 0.1, 2.8, 0.1, "white");
  } else if (id === "he-hua-temple") {
    const z = d * 0.43, gate2 = w * 0.61;
    for (const x of [-w * 0.4, w * 0.4]) {
      box2(x, 0, -d * 0.04, w * 0.18, 9.8, d * 0.83, "stone");
      box2(x, 9.8, -d * 0.04, w * 0.19, 0.25, d * 0.84, "red");
      for (const y of [1.1, 4.3, 7.3]) for (const u of [-w * 0.047, w * 0.047]) multiWindow(x + u, y, z + 0.03, 1.6, 1.9);
    }
    box2(0, 0, -d * 0.2, gate2, 7.1, d * 0.54, "stone");
    curvedRoof(0, 7.1, -d * 0.2, gate2 + 1, d * 0.62, 2.8);
    const shape3 = new T65.Shape();
    shape3.moveTo(-gate2 / 2, 0);
    shape3.lineTo(gate2 / 2, 0);
    shape3.lineTo(gate2 / 2, 6.4);
    shape3.lineTo(-gate2 / 2, 6.4);
    shape3.closePath();
    for (const [x, a, h] of [[-gate2 * 0.35, 3.2, 3.8], [0, 5.6, 5.15], [gate2 * 0.35, 3.2, 3.8]]) {
      const hole = new T65.Path();
      hole.moveTo(x - a / 2, 0);
      hole.lineTo(x - a / 2, h - a / 2);
      hole.absarc(x, h - a / 2, a / 2, Math.PI, 0, true);
      hole.lineTo(x + a / 2, 0);
      hole.closePath();
      shape3.holes.push(hole);
    }
    add2(new T65.ExtrudeGeometry(shape3, { depth: 0.75, bevelEnabled: false, curveSegments: 10 }), "stone", 0, 0, z - 0.45);
    for (const x of [-gate2 * 0.35, gate2 * 0.35]) {
      box2(x, 4.15, z, gate2 * 0.29, 0.75, 1.05, "red");
      curvedRoof(x, 4.9, z, gate2 * 0.32, 3.25, 1.05);
    }
    box2(0, 5.4, z, gate2 * 0.46, 0.75, 1.2, "red");
    curvedRoof(0, 6.15, z, gate2 * 0.51, 3.9, 1.45);
    box2(0, 7.9, z - 0.27, gate2 * 0.49, 0.72, 0.92, "red");
    curvedRoof(0, 8.6, z - 0.27, gate2 * 0.53, 3.65, 1.35);
    sign2("HE HUA TEMPLE", 0, 5.6, z + 0.67, 0.16, "gold");
    for (const x of [-gate2 * 0.26, gate2 * 0.26]) for (let y = 0.8; y < 5.2; y += 0.7) box2(x, y, z + 0.5, 0.18, 0.26, 0.08, "red");
    for (let i = 0; i < 6; i++) box2(0, i * 0.23, z + 0.52 + (5 - i) * 0.4, 5.6, 0.23, 0.4, "stone");
    for (const x of [-gate2 * 0.24, gate2 * 0.24]) {
      add2(new T65.IcosahedronGeometry(0.22, 0), "gold", x, 10.25, z - 0.27);
      box2(x, 10.15, z - 0.27, 0.12, 0.6, 0.12, "gold");
    }
  } else if (id === "haarlemmerpoort") {
    const passage = w * 0.48, wing = (w - passage) / 2;
    for (const x of [-(passage + wing) / 2, (passage + wing) / 2]) {
      box2(x, 0, 0, wing * 0.98, 10.7, d * 0.94, "stone");
      for (const z of [-d * 0.48, d * 0.48]) {
        multiWindow(x, 1.6, z, 2.1, 3.4, z > 0 ? 0 : Math.PI);
        multiWindow(x, 6.6, z, 2.1, 1.6, z > 0 ? 0 : Math.PI);
      }
      box2(x, 10.7, 0, wing + 1, 0.55, d + 0.2, "stone");
    }
    box2(0, 10.35, 0, w + 0.2, 1.4, d * 0.95, "stone");
    box2(0, 11.75, 0, w + 0.6, 0.55, d + 0.4, "stone");
    box2(0, 12.3, 0, passage + 1.5, 1.85, d * 0.81, "stone");
    box2(0, 14.15, 0, passage + 2, 0.2, d * 0.84, "slate");
    for (const side of [-1, 1]) {
      const z = side * d * 0.42;
      for (const x of [-passage * 0.42, -passage * 0.15, passage * 0.15, passage * 0.42]) column(x, 0.1, z, 0.52, 10.25);
      for (let x = -w * 0.48; x <= w * 0.48; x += 0.8) box2(x, 11.5, z + side * 0.85, 0.28, 0.5, 0.22, "stone");
    }
    for (const side of [-1, 1]) {
      const z = side * d * 0.491;
      box2(0, 12.2, z, 4.4, 1.8, 0.23, "stone");
      add2(new T65.CylinderGeometry(1.25, 1.25, 0.15, 20).rotateX(Math.PI / 2), "stone", 0, 13.85, z);
      if (side > 0) clock2(0, 13.85, z + 0.13, 1.15);
      else {
        const g = new T65.CylinderGeometry(0.94, 0.94, 0.2, 20).rotateX(Math.PI / 2);
        add2(g, "dark", 0, 13.85, z - 0.14);
        box2(0, 13.85, z - 0.28, 0.07, 0.75, 0.08, "gold");
        box2(0, 13.82, z - 0.29, 0.6, 0.07, 0.08, "gold");
      }
    }
  } else throw new Error(`No civic builder for ${id}`);
}

