// scripts/landmarks/kriterion-front-lettering.ts
function addKcriterionFrontLettering(b, origin, angle, width = 6.1, height = 0.78) {
  const path3 = new T69.ShapePath();
  for (const command of kriterion_front_lettering_default.commands) {
    const c = command;
    if (c.type === "M") path3.moveTo(c.x, -c.y);
    else if (c.type === "L") path3.lineTo(c.x, -c.y);
    else if (c.type === "Q") path3.quadraticCurveTo(c.x1, -c.y1, c.x, -c.y);
    else if (c.type === "C") path3.bezierCurveTo(c.x1, -c.y1, c.x2, -c.y2, c.x, -c.y);
    else if (c.type === "Z") path3.currentPath.closePath();
  }
  const shapes = path3.toShapes(false), base = new T69.ExtrudeGeometry(shapes, { depth: 0.024, bevelEnabled: false, curveSegments: 8 });
  base.computeBoundingBox();
  const bb = base.boundingBox, size = bb.getSize(new T69.Vector3()), cx2 = (bb.min.x + bb.max.x) / 2, cy = bb.min.y;
  base.translate(-cx2, -cy, 0);
  base.scale(width / size.x, height / size.y, 1);
  const front = new T69.ShapeGeometry(shapes, 8);
  front.translate(-cx2, -cy, 0.027);
  front.scale(width / size.x, height / size.y, 1);
  for (const [geometry, colour] of [[base, "gold"], [front, "red"]]) {
    geometry.rotateY(angle);
    geometry.translate(origin.x, origin.y, origin.z);
    b.add(geometry, colour);
  }
}

