// scripts/landmarks/cinema-palace-builders.ts
function buildCinemaPalaceLandmark(id, w, d, b) {
  const { add: add2, box: box2, sign: sign2, hip: hip2 } = b;
  if (id === "tuschinski") {
    const s = cinema_palace_specs_default.find((s2) => s2.id === id), source = cinema_palace_footprints_default.find((f) => f.id === id), anchor = s.footprint.centre;
    const coord = ([lng, lat]) => new T72.Vector2((lng - anchor[0]) * 111320 * Math.cos(anchor[1] * Math.PI / 180), -(lat - anchor[1]) * 110540);
    const shape3 = new T72.Shape(source.ring.map(coord)), walls = new T72.ExtrudeGeometry(shape3, { depth: 19, bevelEnabled: false });
    walls.rotateX(Math.PI / 2);
    walls.translate(0, 19, 0);
    add2(walls, "stone");
    let roof = new T72.ShapeGeometry(shape3);
    roof.rotateX(Math.PI / 2);
    add2(roof, "slate", 0, 19.04, 0);
    for (const [lng, lat, len, wid] of [[4.894505, 52.366213, 30, 26], [4.894657, 52.36646, 16, 14]]) {
      const p = coord([lng, lat]), v = [[-len / 2, 0, -wid / 2], [len / 2, 0, -wid / 2], [len / 2, 0, wid / 2], [-len / 2, 0, wid / 2], [0, 3, 0]], f = [0, 1, 4, 1, 2, 4, 2, 3, 4, 3, 0, 4], g = new T72.BufferGeometry();
      g.setAttribute("position", new T72.Float32BufferAttribute(f.flatMap((i) => v[i]), 3));
      g.computeVertexNormals();
      g.rotateY(26.6 * Math.PI / 180);
      add2(g, "slate", p.x, 19, p.y);
    }
    const stage = coord([4.894405, 52.366062]);
    box2(stage.x, 19, stage.y, 26, 5.2, 10, "stone", -63.4 * Math.PI / 180);
    box2(stage.x, 24.2, stage.y, 26, 0.8, 10, "slate", -63.4 * Math.PI / 180);
    const kit = frontKitGeometry(TUSCHINSKI, { lng: anchor[0], lat: anchor[1] }, "untextured");
    const colours = { "#8a8188": "stone", "#5f5961": "slate", "#b08a4a": "gold", "#4f6f73": "glass", "#3b3f46": "dark", "#7a2c2a": "brick" };
    for (const tri of kit.tris) {
      const g = new T72.BufferGeometry();
      g.setAttribute("position", new T72.Float32BufferAttribute(tri.p.flatMap((p) => [p[0], p[2], -p[1]]), 3));
      g.computeVertexNormals();
      add2(g, colours[tri.hex] ?? "stone");
    }
    const start = coord(TUSCHINSKI.start), end = coord(TUSCHINSKI.end), u = end.clone().sub(start).normalize(), normal = new T72.Vector2(-u.y, u.x), angle = -Math.atan2(u.y, u.x);
    const front = (x2, z, out2 = 0) => ({ x: start.x + u.x * x2 + normal.x * out2, y: z, z: start.y + u.y * x2 + normal.y * out2 });
    const fb = (x2, y, out2, a, h, c, colour) => {
      const p = front(x2, y, out2);
      box2(p.x, p.y, p.z, a, h, c, colour, angle);
    };
    for (const x2 of [2.4, 12]) {
      const p = front(x2, 26.8, -1.2);
      let dome = new T72.SphereGeometry(1, 12, 6, 0, Math.PI * 2, 0, Math.PI / 2);
      dome.scale(1.85, 4.1, 1.85);
      add2(dome, "glass", p.x, p.y, p.z);
      box2(p.x, 30.9, p.z, 1.1, 1.5, 1.1, "dark");
      hip2(p.x, 32.4, p.z, 1.3, 1.3, 1.2, "glass");
      box2(p.x, 33.6, p.z, 0.1, 1.1, 0.1, "gold");
    }
    for (const [x2, y] of [[2.4, 7.4], [12, 7.4], [2.4, 13.6], [12, 13.6]]) {
      fb(x2, y, 0.9, 2.35, 4, 0.75, "stone");
      for (const dx of [-0.65, 0.65]) {
        fb(x2 + dx, y + 0.25, 1.31, 0.85, 3.4, 0.08, "glass");
        fb(x2 + dx - 0.49, y + 0.15, 1.38, 0.09, 3.6, 0.07, "gold");
      }
    }
    for (const y of [17.1, 18.15, 19.2]) for (let x2 = 4.4; x2 < 10.2; x2 += 0.47) {
      const p = front(x2, y, 0.43);
      add2(new T72.IcosahedronGeometry(0.2, 0), "gold", p.x, p.y, p.z);
    }
    for (const x2 of [0.5, 4.1, 10.25, 13.9]) for (let y = 1; y < 23; y += 0.55) fb(x2, y, 0.7, 0.26, 0.28, 0.24, "slate");
    fb(7.3, 4.25, 1.2, 7.1, 0.45, 2.2, "glass");
    fb(7.3, 4.7, 1.2, 7.2, 0.27, 2.3, "gold");
    const letters3 = { T: ["111", "010", "010", "010", "010"], U: ["101", "101", "101", "101", "111"], S: ["111", "100", "111", "001", "111"], C: ["111", "100", "100", "100", "111"], H: ["101", "101", "111", "101", "101"], I: ["111", "010", "010", "010", "111"], N: ["1001", "1101", "1011", "1001", "1001"], K: ["101", "110", "100", "110", "101"] };
    let x = 4.3;
    for (const ch of "TUSCHINSKI") {
      const rows = letters3[ch];
      for (let j = 0; j < 5; j++) for (let k = 0; k < rows[j].length; k++) if (rows[j][k] === "1") fb(x + k * 0.15, 5.05 + (4 - j) * 0.15, 1.7, 0.12, 0.12, 0.1, "gold");
      x += (rows[0].length + 1) * 0.15;
    }
    for (const x2 of [0.3, 14.2]) {
      const p = front(x2, 0, 0.7);
      box2(p.x, 0, p.z, 0.08, 37, 0.08, "gold");
    }
  } else if (id === "pathe-city") {
    const front = d / 2;
    box2(0, 0, 0, w * 0.97, 17.8, d * 0.97, "stone");
    box2(0, 17.8, 0, w * 0.98, 0.3, d * 0.98, "slate");
    box2(-w * 0.08, 18.1, -d * 0.17, w * 0.64, 5.3, d * 0.5, "stone");
    box2(-w * 0.08, 23.4, -d * 0.17, w * 0.65, 0.35, d * 0.51, "slate");
    const tx = w * 0.36;
    box2(tx, 0, front - 4.1, w * 0.16, 31.1, 7.3, "stone");
    box2(tx, 31.1, front - 4.1, w * 0.17, 0.4, 7.5, "slate");
    for (let x = tx - w * 0.065; x <= tx + w * 0.07; x += w * 0.033) box2(x, 5.5, front - 0.35, 0.22, 23, 0.16, "white");
    add2(new T72.CylinderGeometry(1.45, 1.45, 25.1, 16), "glass", tx + w * 0.075, 17.05, front - 0.3);
    for (let y = 5.2; y <= 29.5; y += 1.7) {
      add2(new T72.CylinderGeometry(1.5, 1.5, 0.13, 16), "frame", tx + w * 0.075, y, front - 0.3);
    }
    for (let i = 0; i < 12; i++) {
      let a = i * Math.PI / 6;
      box2(tx + w * 0.075 + 1.48 * Math.sin(a), 4.5, front - 0.3 + 1.48 * Math.cos(a), 0.08, 25.1, 0.08, "frame");
    }
    box2(-w * 0.3, 1, front + 0.04, w * 0.14, 16.2, 0.2, "glass");
    for (let x = -w * 0.36; x < -w * 0.23; x += 0.6) box2(x, 1, front + 0.18, 0.08, 16.2, 0.08, "frame");
    for (let y = 2; y < 17; y += 1.8) box2(-w * 0.3, y, front + 0.18, w * 0.14, 0.08, 0.08, "frame");
    const sx = w * 0.015, sw = w * 0.45;
    box2(sx, 0, front + 0.04, sw, 3.3, 0.22, "glass");
    for (let x = sx - sw / 2; x <= sx + sw / 2; x += 2.4) box2(x, 0, front + 0.2, 0.12, 3.3, 0.08, "frame");
    sign2("CITY", sx, 13.8, front + 0.16, 0.62, "dark");
    sign2("THEATER", sx, 12.15, front + 0.16, 0.23, "dark");
    box2(sx, 6.3, front + 0.2, sw * 0.95, 4.4, 0.28, "slate");
    box2(sx, 6.6, front + 0.38, sw * 0.9, 3.8, 0.1, "glass");
    box2(sx, 3.6, front + 0.65, sw + 0.8, 0.35, 1.45, "slate");
    sign2("PATHE", sx, 3.95, front + 1.43, 0.27, "gold");
    for (const x of [-w * 0.43, -w * 0.15]) for (const y of [4.2, 8.5, 12.8]) box2(x, y, front + 0.13, w * 0.1, 2, 0.15, "glass");
  } else throw new Error(`No cinema palace builder for ${id}`);
}

