    box2(ex, 0.1, front + 0.32, doorWidth - 0.18, 3.38, 0.08, "glass");
    for (const dx of [-2.22, 0, 2.22]) box2(ex + dx, 0.1, front + 0.4, 0.1, 3.45, 0.08, "gold");
    box2(ex, 2.55, front + 0.4, doorWidth, 0.1, 0.08, "gold");
    box2(ex, 5.25, front + 0.17, 4.7, 9.6, 0.08, "dark");
    const col = 0.43, row = 0.25;
