// scripts/landmarks/memorial-builders.ts
function buildMemorialLandmark(id, _w, _d, b) {
  if (id !== "homomonument") throw new Error(`Unknown memorial ${id}`);
  const source = memorial_footprints_default.find((s) => s.id === id), spec = memorial_specs_default.find((s) => s.id === id), anchor = spec.surveyed.anchor;
  const points = source.corners.map(([lng, lat]) => new T79.Vector2(
    (lng - anchor[0]) * 111320 * Math.cos(anchor[1] * Math.PI / 180),
    (anchor[1] - lat) * 111320
  ));
  function slab(ring, top, depth) {
    const shape3 = new T79.Shape(ring);
    const g = new T79.ExtrudeGeometry(shape3, { depth, bevelEnabled: false });
    g.rotateX(Math.PI / 2);
    g.translate(0, top, 0);
    b.add(g, "pink");
  }
  const triangles = points.map((tip2, i) => [
    tip2,
    tip2.clone().lerp(points[(i + 1) % 3], 10 / tip2.distanceTo(points[(i + 1) % 3])),
    tip2.clone().lerp(points[(i + 2) % 3], 10 / tip2.distanceTo(points[(i + 2) % 3]))
  ]);
  slab(triangles[0], 0.6, 0.6);
  slab(triangles[2], 0.06, 0.06);
  const [tip, left, right] = triangles[1];
  const limits = [0, 0.4, 0.6, 0.8, 1], heights = [0.04, 0.18, 0.32, 0.46];
  for (let i = 0; i < 4; i++) {
    const lo = limits[i], hi = limits[i + 1];
    const ring = lo === 0 ? [tip, tip.clone().lerp(left, hi), tip.clone().lerp(right, hi)] : [
      tip.clone().lerp(left, lo),
      tip.clone().lerp(left, hi),
      tip.clone().lerp(right, hi),
      tip.clone().lerp(right, lo)
    ];
    slab(ring, heights[i], heights[i]);
  }
  for (let i = 0; i < 3; i++) {
    const a = points[i], q = points[(i + 1) % 3], distance2 = a.distanceTo(q);
    const start = a.clone().lerp(q, 10 / distance2), end = q.clone().lerp(a, 10 / distance2);
    const delta = end.clone().sub(start), normal = new T79.Vector2(-delta.y, delta.x).normalize().multiplyScalar(0.09);
    slab([start.clone().add(normal), end.clone().add(normal), end.clone().sub(normal), start.clone().sub(normal)], 0.055, 0.055);
  }
}

