        box2(xx, y, rz - 0.09, 1.9, 4.3, 0.18, "stone");
        box2(xx, y + 0.12, rz - 0.22, 1.65, 4.1, 0.08, "glass");
        box2(xx, y + 0.12, rz - 0.28, 0.06, 4.1, 0.05, "gold");
        box2(xx, y + 2.2, rz - 0.28, 1.65, 0.06, 0.05, "gold");
