      for (const yy of [0.3, 1, 6, 6.3, 11.5]) box2(cx3, yy, rz - 0.08, end, 0.22, 0.2, "stone");
      for (const xx of [lo - 0.04, hi + 0.04]) for (let z = rz + 1.8; z < fz - 1; z += 3.05) for (const yy of [1.4, 6.8]) {
        box2(xx, yy, z, 0.14, 4, 1.65, "glass");
        box2(xx, yy + 4.03, z, 0.26, 0.13, 2.05, "stone");
        box2(xx, yy + 2.2, z, 0.2, 0.07, 1.65, "gold");
      }
      box2(cx3, 12.15, front - 0.5, 1.8, 1.15, 0.5, "stone");
      box2(cx3, 12.3, front - 0.18, 1.3, 0.8, 0.08, "glass");
