      add2(new T84.CylinderGeometry(0.19, 0.2, 2.7, 8), "stone", cx2, 3.82, 1.58);
      for (const y of [0.27, 2.46, 5.18, 5.44]) add2(new T84.CylinderGeometry(0.28, 0.28, 0.14, 8), "white", cx2, y, 1.58);
