  box2(0, 7.46, -1.74, 9.12, 0.23, 0.32, "stone");
  for (const x of [-2.42, -1.25, 1.25, 2.42]) add2(new T84.IcosahedronGeometry(0.26, 0), "stone", x, 6.93, -1.82);
