  const paths = features.filter((f) => f.tags.highway === "footway").map((f) => f.localEastSouthMetres);
  const shape3 = (ps2) => new T93.Shape(ps2.map((p) => new T93.Vector2(...p)));
  const add2 = (g, c, role) => {
    g.userData.role = role;
    b.add(g, c);
  };
