    const start = new T93.Vector3(...a), end = new T93.Vector3(...q), v = end.clone().sub(start), g = new T93.BoxGeometry(w, v.length(), w);
    g.applyQuaternion(new T93.Quaternion().setFromUnitVectors(new T93.Vector3(0, 1, 0), v.normalize()));
