    for (let u = 0.35; u < l; u += 2.6) for (const side of [-1, 1]) box2(a[0] + dx * u + nx * side * 0.37, -0.62, a[1] + dz * u + nz * side * 0.37, 0.14, 0.6, 0.14, "dark", "deck-support");
