// scripts/landmarks/amsta-de-poort-builder.ts
function buildAmstaDePoort(_id, _w, _d, b) {
  const { add: add2, box: box2 } = b, angle = amsta_de_poort_footprints_default.authorHeadingDegrees * Math.PI / 180;
  const project = (p) => {
    const east = (p[0] - amsta_de_poort_footprints_default.anchor[0]) * 111320 * Math.cos(amsta_de_poort_footprints_default.anchor[1] * Math.PI / 180);
    const north = (p[1] - amsta_de_poort_footprints_default.anchor[1]) * 110540;
    return new T110.Vector2(east * Math.sin(angle) + north * Math.cos(angle), east * Math.cos(angle) - north * Math.sin(angle));
  };
  const outline = amsta_de_poort_footprints_default.parent.geometry.coordinates[0].slice(0, -1).map(project);
  function volume(ring, bottom, top, colour = "frame", keepTop = true) {
    const g = new T110.ExtrudeGeometry(new T110.Shape(ring), { depth: top - bottom, bevelEnabled: false });
    g.rotateX(Math.PI / 2);
    g.translate(0, top, 0);
    if (keepTop) {
      add2(g, colour);
      return;
    }
    const flat = g.index ? g.toNonIndexed() : g, positions = flat.getAttribute("position"), normals = flat.getAttribute("normal"), out2 = [];
    for (let i = 0; i < positions.count; i += 3) {
      if ([0, 1, 2].every((j) => normals.getY(i + j) > 0.9)) continue;
      for (let j = 0; j < 3; j++) out2.push(positions.getX(i + j), positions.getY(i + j), positions.getZ(i + j));
    }
    const shell = new T110.BufferGeometry();
    shell.setAttribute("position", new T110.Float32BufferAttribute(out2, 3));
    shell.computeVertexNormals();
    if (flat !== g) flat.dispose();
    g.dispose();
    add2(shell, colour);
  }
  function plane(x, y, z, w, h, colour, a = 0) {
    add2(new T110.PlaneGeometry(w, h), colour, x, y + h / 2, z, a);
  }
  function glazing(x, y, z, w, h, lights, a = 0, panel = true) {
    const nx = Math.sin(a), nz = Math.cos(a), tx = Math.cos(a), tz = -Math.sin(a);
    plane(x, y, z, w, h, "white", a);
    plane(x + nx * 0.035, y + 0.1, z + nz * 0.035, w - 0.18, h - 0.2, "glass", a);
    if (panel) plane(x + nx * 0.055, y + 0.1, z + nz * 0.055, w - 0.18, 0.32, "gold", a);
    for (let i = 1; i < lights; i++) {
      const u = -w / 2 + w * i / lights;
      box2(x + u * tx + nx * 0.07, y, z + u * tz + nz * 0.07, 0.07, h, 0.09, "white", a);
    }
    box2(x + nx * 0.075, y + h * 0.73, z + nz * 0.075, w, 0.065, 0.09, "white", a);
  }
  volume(outline.map((p) => new T110.Vector2(p.x, Math.min(p.y, 20.25))), 0, 3.3, "dark");
  for (const zone of amsta_de_poort_footprints_default.roofZones) {
    const ring = zone.planMetres.map((p) => new T110.Vector2(p[0], p[1]));
    volume(ring, 3.3, zone.topMetres, "frame", false);
    const lid = new T110.ShapeGeometry(new T110.Shape(ring));
    lid.rotateX(Math.PI / 2);
    const index = lid.index;
    for (let i = 0; i < index.count; i += 3) {
      const v = index.getX(i + 1);
      index.setX(i + 1, index.getX(i + 2));
      index.setX(i + 2, v);
    }
    lid.computeVertexNormals();
    add2(lid, "slate", 0, zone.topMetres + 0.035, 0);
  }
  const front = 22.94;
  for (let x = -35.9; x <= 23.3; x += 3.28) {
    box2(x, 0, 21.55, 0.44, 3.36, 0.56, "brick");
    glazing(x + 1.6, 0.28, 20.32, 2.74, 2.68, 2, 0, false);
  }
  box2(-5.8, 3.15, 21.72, 61, 0.48, 2.58, "white");
  const rows = [4.16, 7.38, 10.6, 13.82, 17.04, 20.26];
  for (const y of rows) {
    for (let i = 0; i < 6; i++) {
      const x = -32.2 + i * 9.8;
      glazing(x, y, front, 5.35, 2.3, 6);
      glazing(x + 4.85, y + 0.02, front, 3.12, 2.27, 2, 0, false);
      box2(x + 2.95, y - 0.12, front + 0.02, 0.28, 3.1, 0.18, "dark");
    }
    box2(-5.8, y - 0.15, front, 59.8, 0.15, 0.18, "white");
  }
  for (const x of [-5.2, 15.5]) {
    box2(x, 4.01, front + 0.2, 3.55, 0.2, 0.56, "white");
    for (const y of [4.2, 7.4]) glazing(x, y, front + 0.47, 3.22, 2.9, 4);
    for (const dx of [-1.67, 1.67]) box2(x + dx, 4.12, front + 0.42, 0.12, 6.34, 0.18, "gold");
    box2(x, 10.47, front + 0.26, 3.57, 0.2, 0.67, "white");
  }
  box2(-5.8, 23.41, front - 0.06, 59.5, 0.25, 0.32, "white");
  for (let x = -26.5; x <= 12; x += 3.05) glazing(x, 24.36, 19.92, 2.83, 1.85, 2, 0, false);
  box2(-7.3, 27.35, 19.98, 42.8, 0.39, 0.28, "gold");
  for (const x of [-27.9, 14]) box2(x, 23.75, 19.93, 0.2, 3.6, 0.26, "white");
  box2(3.56, 27.5, 11.93, 3.3, 4.2, 2.31, "frame");
  box2(3.56, 31.69, 11.93, 3.43, 0.12, 2.43, "slate");
  for (const x of [0.2, 1.15]) {
    box2(x, 27.6, 14.3, 0.1, 3.75, 0.1, "dark");
    box2(x, 29.35, 14.3, 0.22, 1.48, 0.19, "frame");
  }
  const inside = (x, z, ring) => {
    let yes = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const p = ring[i], q = ring[j];
      if (p[1] > z !== q[1] > z && x < (q[0] - p[0]) * (z - p[1]) / (q[1] - p[1]) + p[0]) yes = !yes;
    }
    return yes;
  };
  for (const zone of amsta_de_poort_footprints_default.roofZones) {
    const ring = zone.planMetres, vectors = ring.map((p) => new T110.Vector2(p[0], p[1]));
    const clockwise = T110.ShapeUtils.area(vectors) < 0;
    for (let i = 0; i < ring.length; i++) {
      const p = ring[i], q = ring[(i + 1) % ring.length], dx = q[0] - p[0], dz = q[1] - p[1], len = Math.hypot(dx, dz);
      if (len < 4) continue;
      const nx = clockwise ? -dz / len : dz / len, nz = clockwise ? dx / len : -dx / len;
      const mx = (p[0] + q[0]) / 2, mz = (p[1] + q[1]) / 2;
      if (mz > 17 && nz > 0.6) continue;
      const adjacent = Math.max(3.3, ...amsta_de_poort_footprints_default.roofZones.filter((other) => other !== zone && inside(mx + nx * 0.18, mz + nz * 0.18, other.planMetres)).map((other) => other.topMetres));
      const count = Math.max(1, Math.floor(len / 3.35)), a = Math.atan2(nx, nz);
      for (let j = 0; j < count; j++) {
        const t = (j + 0.5) / count, x = p[0] + dx * t + nx * 0.1, z = p[1] + dz * t + nz * 0.1;
        for (const y of [...rows, 24.36]) if (y > adjacent + 0.15 && y + 2.1 < zone.topMetres - 0.25) glazing(x, y, z, Math.min(2.62, len / count - 0.42), 2.1, 2, a, false);
      }
    }
  }
  plane(5, 3.82, front + 0.4, 8.8, 0.8, "white");
  b.sign("AMSTA DE POORT", 5, 4.03, front + 0.45, 0.054, "dark");
}

