// scripts/landmarks/amstel-towers-builders.ts
function buildAmstelTowerLandmark(id, _width, _depth, b) {
  const spec = amstel_towers_specs_default.find((s) => s.id === id), source = amstel_towers_footprints_default.find((s) => s.id === id);
  if (!spec || !source) throw new Error(`No Amstel tower source for ${id}`);
  const [lng, lat] = spec.surveyed.anchor, heading = 69.7 * Math.PI / 180;
  const local = ([x, y]) => {
    const e = (x - lng) * 111320 * Math.cos(lat * Math.PI / 180), n = (y - lat) * 110540;
    return [e * Math.sin(heading) + n * Math.cos(heading), e * Math.cos(heading) - n * Math.sin(heading)];
  };
  function simplify(ring) {
    let r = ring.slice();
    if (r.length > 1 && Math.hypot(r[0][0] - r.at(-1)[0], r[0][1] - r.at(-1)[1]) < 1e-3) r.pop();
    let changed = true;
    while (changed && r.length > 4) {
      changed = false;
      for (let i = 0; i < r.length; i++) {
        const a = r[(i + r.length - 1) % r.length], q = r[i], c = r[(i + 1) % r.length];
        const length = Math.hypot(c[0] - a[0], c[1] - a[1]);
        const distance2 = length ? Math.abs((q[0] - a[0]) * (c[1] - a[1]) - (q[1] - a[1]) * (c[0] - a[0])) / length : 0;
        if (distance2 < 0.075 && Math.hypot(q[0] - a[0], q[1] - a[1]) + Math.hypot(q[0] - c[0], q[1] - c[1]) < length + 0.08) {
          r.splice(i, 1);
          changed = true;
          break;
        }
      }
    }
    return r;
  }
  const polygons = source.geometry.coordinates.map((poly) => poly.map((r) => simplify(r.map(local))));
  const clip = (r, axis, at, above) => {
    const out2 = [];
    for (let i = 0; i < r.length; i++) {
      const a = r[i], q = r[(i + 1) % r.length], ia = above ? a[axis] >= at : a[axis] <= at, iq = above ? q[axis] >= at : q[axis] <= at;
      if (ia) out2.push(a);
      if (ia !== iq) {
        const t = (at - a[axis]) / (q[axis] - a[axis]);
        out2.push([a[0] + (q[0] - a[0]) * t, a[1] + (q[1] - a[1]) * t]);
      }
    }
    return out2;
  };
  const section = (r, x0, x1, z0, z1) => clip(clip(clip(clip(r, 0, x0, true), 0, x1, false), 1, z0, true), 1, z1, false);
  function part(x0, x1, z0, z1, base, top, colour) {
    const walls = [];
    for (const polygon of polygons) {
      const rings = polygon.map((r) => section(r, x0, x1, z0, z1));
      if (rings[0].length < 3) continue;
      walls.push(rings[0]);
      const shape3 = new T111.Shape(rings[0].map((p) => new T111.Vector2(...p)));
      for (const hole of rings.slice(1)) if (hole.length >= 3) shape3.holes.push(new T111.Path(hole.map((p) => new T111.Vector2(...p))));
      const geometry = new T111.ExtrudeGeometry(shape3, { depth: top - base, bevelEnabled: false });
      geometry.rotateX(Math.PI / 2);
      b.add(geometry, colour, 0, top, 0);
    }
    return walls;
  }
  function glassGrid(rings, base, top, pitch = 3.45, mullion = "stone") {
    for (const ring of rings) {
      const area = ring.reduce((a, p, i) => a + p[0] * ring[(i + 1) % ring.length][1] - ring[(i + 1) % ring.length][0] * p[1], 0);
      for (let i = 0; i < ring.length; i++) {
        const a = ring[i], q = ring[(i + 1) % ring.length], dx = q[0] - a[0], dz = q[1] - a[1], length = Math.hypot(dx, dz);
        if (length < 1) continue;
        const nx = (area > 0 ? dz : -dz) / length, nz = (area > 0 ? -dx : dx) / length;
        const x = (a[0] + q[0]) / 2 + nx * 0.06, z = (a[1] + q[1]) / 2 + nz * 0.06, angle = -Math.atan2(dz, dx);
        for (let y = base + 0.7; y + pitch * 0.77 < top - 0.3; y += pitch) b.box(x, y, z, length - 0.16, pitch * 0.72, 0.12, "glass", angle);
        const count = Math.max(1, Math.round(length / 2.25));
        for (let j = 0; j <= count; j++) {
          const t = j / count;
          b.box(a[0] + dx * t + nx * 0.15, base, a[1] + dz * t + nz * 0.15, 0.24, top - base, 0.17, mullion, angle);
        }
      }
    }
  }
  const office = (x0, x1, z0, z1, base, top, colour = "stone", pitch = 3.45, mullion = "stone") => {
    const ring = part(x0, x1, z0, z1, base, top, colour);
    glassGrid(ring, base, top, pitch, mullion);
    return ring;
  };
  if (id === "rembrandt-tower") {
    office(-100, 100, -100, 100, 0, 22.05, "stone", 3.4);
    office(-18.7, 20.8, -16.9, 22, 22.05, 37.02, "stone", 3.7);
    office(-15.4, 17.9, -13.6, 19.1, 37.02, 106.85, "stone", 3.45);
    for (const x of [-14, 16.1]) for (const z of [-11.9, 17.2]) {
      const corners = part(x - 3, x + 3, z - 3, z + 3, 37.02, 120.47, "glass");
      glassGrid(corners, 37.02, 120.47, 3.45, "frame");
      b.box(x, 120.47, z, 6, 0.2, 6, "frame");
    }
    office(-13.2, 16.1, -13, 17.6, 106.85, 110.1, "stone", 3.25);
    office(-11.6, 14.1, -10.3, 14.8, 110.1, 120.5, "stone", 3.45);
    office(-9.2, 12.3, -7.9, 13.1, 120.5, 132.4, "stone", 3.8);
    b.box(1.55, 132.4, 2.6, 7, 2.6, 6.8, "stone");
    for (const z of [-1, 6.2]) b.box(1.55, 133.2, z, 4.8, 1.5, 0.12, "dark");
    for (const y of [135, 136.2, 137.3]) b.add(new T111.CylinderGeometry(1.4, 1.4, 0.33, 10), "stone", 1.55, y, 2.6);
    b.add(new T111.CylinderGeometry(0.22, 0.42, 12.3, 8), "white", 1.55, 143.65, 2.6);
    b.box(1.55, 149.7, 2.6, 0.48, 0.3, 0.48, "gold");
    b.box(1.5, 4.8, 23.8, 25.4, 0.42, 5.5, "stone");
    for (const x of [-10.5, -5, 1.5, 8, 13.5]) b.box(x, 0, 25.7, 0.4, 4.8, 0.4, "stone");
    b.box(1.5, 5.2, 26.49, 12.4, 10.8, 0.13, "glass");
    for (const x of [-4.6, 1.5, 7.6]) b.box(x, 5.2, 26.62, 0.23, 10.8, 0.15, "frame");
    b.sign("REMBRANDT", 1.5, 4.94, 26.61, 0.15, "dark");
  } else if (id === "breitner-tower") {
    office(-100, 100, -100, 13, 0, 16.55, "white", 3.7, "frame");
    part(-100, 100, -100, 13, 16.55, 16.85, "slate");
    office(-13.5, 9.5, 13, 20, 0, 13.1, "white", 4, "frame");
    office(-13.5, -8.8, 13, 49.3, 0, 63.9, "glass", 3.4, "frame");
    office(-8.8, 6.1, 20, 53.7, 0, 93.45, "glass", 3.4, "frame");
    office(6.1, 16, 20, 53.7, 0, 82.6, "glass", 3.4, "frame");
    part(-3.4, 2.4, 39.5, 47.2, 93.45, 95, "slate");
    b.box(-0.5, 4.4, 16.3, 19.2, 0.27, 4.6, "white");
    for (const x of [-8.6, 7.6]) b.box(x, 0, 17.8, 0.26, 4.4, 0.26, "frame");
  } else if (id === "mondriaan-tower") {
    office(-100, -14.7, -100, 100, 0, 11.35, "stone", 3.55);
    office(-14.7, 28.5, -5.65, 9.3, 0, 11.35, "stone", 11);
    office(-14.7, -4.7, -5.65, 9.3, 11.35, 92.25, "stone", 3.5);
    office(-4.7, 28.5, -5.65, 9.3, 11.35, 117.3, "stone", 3.5);
    office(0, 17, -14.4, -5.65, 0, 11.35, "glass", 11, "frame");
    office(0, 22, 9.3, 15, 0, 11.35, "glass", 11, "frame");
    office(0, 17, -14.4, -5.65, 11.35, 106.5, "glass", 3.5, "frame");
    office(0, 22, 9.3, 15, 11.35, 106.5, "glass", 3.5, "frame");
    b.box(7.6, 106.5, -8.55, 14.7, 8, 6, "glass");
    for (const x of [0.5, 5.2, 10, 14.7]) b.box(x, 106.5, -11.63, 0.18, 8.1, 0.12, "frame");
    for (const y of [106.5, 110.3, 114.5]) b.box(7.6, y, -11.63, 14.8, 0.13, 0.12, "frame");
    part(0.5, 27.5, -5.6, 9.2, 117.3, 119, "stone");
    b.box(4.7, 119, 0.9, 5.6, 3.3, 4.8, "slate");
    b.box(-24.5, 4, 8.7, 10.1, 0.28, 3.7, "stone");
    b.sign("MONDRIAAN", -22, 5, 9.4, 0.1, "dark");
  } else throw new Error(`No Amstel tower builder for ${id}`);
}

