// scripts/landmarks/piramides-builder.ts
function buildPiramides(_width, _depth, b) {
  const [lng, lat] = piramides_spec_default.surveyed.anchor, h = 81.5 * Math.PI / 180;
  function local([x, y]) {
    const e = (x - lng) * 111320 * Math.cos(lat * Math.PI / 180), n = (y - lat) * 110540;
    return [e * Math.sin(h) + n * Math.cos(h), e * Math.cos(h) - n * Math.sin(h)];
  }
  function simplify(points) {
    const ring = points.slice();
    ring.pop();
    let again = true;
    while (again && ring.length > 4) {
      again = false;
      for (let i = 0; i < ring.length; i++) {
        const a = ring[(i + ring.length - 1) % ring.length], p = ring[i], q = ring[(i + 1) % ring.length];
        const length = Math.hypot(q[0] - a[0], q[1] - a[1]);
        const deviation = length ? Math.abs((p[0] - a[0]) * (q[1] - a[1]) - (p[1] - a[1]) * (q[0] - a[0])) / length : 0;
        if (deviation < 0.095 && Math.hypot(p[0] - a[0], p[1] - a[1]) + Math.hypot(p[0] - q[0], p[1] - q[1]) < length + 0.08) {
          ring.splice(i, 1);
          again = true;
          break;
        }
      }
    }
    return ring;
  }
  for (const part of piramides_footprints_default.parts) {
    for (const polygon of part.geometry.coordinates) {
      const ring = simplify(polygon[0].map(local));
      const shape3 = new T112.Shape(ring.map((p) => new T112.Vector2(...p)));
      const wall = new T112.ExtrudeGeometry(shape3, { depth: part.height - part.base, bevelEnabled: false });
      wall.rotateX(Math.PI / 2);
      b.add(wall, "brick", 0, part.height, 0);
      const roof = new T112.ShapeGeometry(shape3);
      roof.rotateX(Math.PI / 2);
      const indices = roof.index;
      for (let j = 0; j < indices.count; j += 3) {
        const a = indices.getX(j);
        indices.setX(j, indices.getX(j + 2));
        indices.setX(j + 2, a);
      }
      roof.computeVertexNormals();
      b.add(roof, "slate", 0, part.height + 0.012, 0);
      const area = ring.reduce((sum, p, i) => sum + p[0] * ring[(i + 1) % ring.length][1] - ring[(i + 1) % ring.length][0] * p[1], 0);
      for (let i = 0; i < ring.length; i++) {
        const a = ring[i], q = ring[(i + 1) % ring.length], dx = q[0] - a[0], dz = q[1] - a[1], length = Math.hypot(dx, dz);
        if (length < 0.8) continue;
        const nx = (area > 0 ? dz : -dz) / length, nz = (area > 0 ? -dx : dx) / length, angle = -Math.atan2(dz, dx);
        const count = Math.max(1, Math.floor(length / (nz < -0.7 ? 3 : 2.4)));
        const floors = part.base === 0 ? [1.2] : [part.base + 0.65, part.base + 3.4];
        for (const y of floors) {
          if (y + 1.92 > part.height - 0.1) continue;
          for (let j = 0; j < count; j++) {
            const t = (j + 0.5) / count, x = a[0] + dx * t, z = a[1] + dz * t;
            b.box(x + nx * 0.045, y, z + nz * 0.045, 1.22, 1.9, 0.11, "white", angle);
            b.box(x + nx * 0.115, y + 0.15, z + nz * 0.115, 0.95, 1.57, 0.085, "glass", angle);
          }
          b.box((a[0] + q[0]) / 2 + nx * 0.028, y - 0.36, (a[1] + q[1]) / 2 + nz * 0.028, length, 0.07, 0.06, "red", angle);
        }
        if (part.height < 55 && Math.abs(nz) < 0.6) {
          b.box((a[0] + q[0]) / 2 + nx * 0.06, part.height + 0.53, (a[1] + q[1]) / 2 + nz * 0.06, length, 0.075, 0.075, "frame", angle);
          const posts = Math.max(1, Math.ceil(length / 2));
          for (let j = 0; j <= posts; j++) b.box(a[0] + dx * j / posts + nx * 0.06, part.height, a[1] + dz * j / posts + nz * 0.06, 0.065, 0.58, 0.065, "frame", angle);
        }
      }
    }
  }
  for (let y = 5; y < 27; y += 2.75) {
    b.box(-13, y, 12.24, 7.1, 0.17, 1.55, "stone");
    b.box(-13, y + 0.9, 13, 7.1, 0.085, 0.085, "white");
    for (let x = -16.3; x <= -9.6; x += 1.12) b.box(x, y + 0.2, 13, 0.065, 0.78, 0.065, "white");
  }
  for (const x of [-16.5, -13, -9.5]) b.box(x, 0, 13, 0.15, 27.7, 0.15, "white");
  b.box(-13, 4.52, 12.22, 7.5, 0.28, 1.9, "white");
  b.box(-13, 0, 11.62, 5.7, 4.45, 0.13, "glass");
  b.sign("DE PIRAMIDES", -13, 4.64, 13.2, 0.13, "dark");
}

