// scripts/landmarks/park-pavilion-builders.ts
function buildParkPavilionLandmark(id, _w, _d, b) {
  if (id !== "vondelpark-bandstand") throw new Error(`No park pavilion builder for ${id}`);
  const { add: add2, box: box2 } = b, s = park_pavilion_specs_default[0], a = s.surveyed.anchor;
  const h = (90 + s.surveyed.northOffsetDegrees) * Math.PI / 180;
  const outline = park_pavilion_footprints_default[0].parts[0].polygons[0][0].slice(0, -1).map(([lng, lat]) => {
    const east = (lng - a[0]) * 111320 * Math.cos(a[1] * Math.PI / 180), north = (lat - a[1]) * 110540;
    return new T128.Vector2(east * Math.sin(h) + north * Math.cos(h), east * Math.cos(h) - north * Math.sin(h));
  });
  const beam = (p, q, radius, colour) => {
    const start = new T128.Vector3(...p), end = new T128.Vector3(...q), delta = end.clone().sub(start);
    const g = new T128.CylinderGeometry(radius, radius, delta.length(), 6);
    g.applyQuaternion(new T128.Quaternion().setFromUnitVectors(new T128.Vector3(0, 1, 0), delta.clone().normalize()));
    const mid = start.add(end).multiplyScalar(0.5);
    add2(g, colour, mid.x, mid.y, mid.z);
  };
  const cylinder = (radius, y, height, colour, x = 0, z = 0, segments = 10) => add2(new T128.CylinderGeometry(radius, radius, height, segments), colour, x, y + height / 2, z, Math.PI / 10);
  const floorHeight = 1.48, roofEaves = 6.1, roofPeak = 7.02;
  cylinder(3.72, 0, floorHeight, "white");
  cylinder(3.87, floorHeight, 0.12, "stone");
  cylinder(3.75, 0, 0.17, "stone");
  const cols = Array.from({ length: 10 }, (_, i) => {
    const angle = (18 + i * 36) * Math.PI / 180;
    return { x: Math.sin(angle) * 3.67, z: Math.cos(angle) * 3.67 };
  });
  for (const p of cols) {
    box2(p.x, floorHeight, p.z, 0.4, 0.19, 0.4, "dark");
    cylinder(0.21, 1.67, 0.42, "dark", p.x, p.z, 8);
    cylinder(0.26, 2.09, 0.12, "frame", p.x, p.z, 10);
    add2(new T128.CylinderGeometry(0.12, 0.165, 3.19, 12), "dark", p.x, 3.805, p.z);
    for (let k = 0; k < 8; k++) {
      const theta = k * Math.PI / 4;
      cylinder(0.018, 2.29, 3, "frame", p.x + Math.sin(theta) * 0.141, p.z + Math.cos(theta) * 0.141, 4);
    }
    cylinder(0.195, 5.35, 0.12, "frame", p.x, p.z);
    cylinder(0.24, 5.47, 0.13, "dark", p.x, p.z);
    box2(p.x, 5.6, p.z, 0.48, 0.15, 0.48, "dark");
    for (const dx of [-0.18, 0.18]) for (const dz of [-0.18, 0.18])
      add2(new T128.ConeGeometry(0.08, 0.22, 4), "frame", p.x + dx, 5.52, p.z + dz);
  }
  for (let i = 0; i < 10; i++) {
    const p = cols[i], q = cols[(i + 1) % 10], mid = { x: (p.x + q.x) / 2, z: (p.z + q.z) / 2 };
    const normal = Math.atan2(mid.x, mid.z);
    beam([p.x, 5.78, p.z], [q.x, 5.78, q.z], 0.075, "dark");
    beam([p.x, 6, p.z], [q.x, 6, q.z], 0.055, "dark");
    for (let j = 0; j < 8; j++) {
      const t = j / 8, u = (j + 1) / 8;
      beam(
        [p.x + (q.x - p.x) * t, 5.77 - 0.4 * Math.sin(t * Math.PI), p.z + (q.z - p.z) * t],
        [p.x + (q.x - p.x) * u, 5.77 - 0.4 * Math.sin(u * Math.PI), p.z + (q.z - p.z) * u],
        0.04,
        "dark"
      );
    }
    for (const t of [0.18, 0.37, 0.63, 0.82]) {
      const x = p.x + (q.x - p.x) * t, z = p.z + (q.z - p.z) * t;
      add2(new T128.TorusGeometry(0.115, 0.021, 4, 8), "dark", x, 5.8, z, normal);
    }
    if (i === 9) continue;
    beam([p.x, 2.48, p.z], [q.x, 2.48, q.z], 0.055, "dark");
    beam([p.x, 1.71, p.z], [q.x, 1.71, q.z], 0.038, "dark");
    for (let j = 1; j < 9; j++) {
      const t = j / 9, x = p.x + (q.x - p.x) * t, z = p.z + (q.z - p.z) * t;
      cylinder(0.023, 1.72, 0.76, "dark", x, z, 4);
      if (j % 2 === 0) add2(new T128.TorusGeometry(0.115, 0.022, 4, 8), "dark", x, 2.05, z, normal);
    }
  }
  const vertices = [];
  for (let i = 0; i < outline.length; i++) {
    const p = outline[i], q = outline[(i + 1) % outline.length];
    vertices.push(q.x, roofEaves, q.y, 0, roofPeak, 0, p.x, roofEaves, p.y);
    beam([p.x, 6.03, p.y], [q.x, 6.03, q.y], 0.105, "white");
    beam([0, 5.94, 0], [p.x, 5.94, p.y], 0.042, "stone");
    for (let j = 1; j < 6; j++) {
      const t = j / 6, x = p.x + (q.x - p.x) * t, z = p.y + (q.y - p.y) * t;
      const outward = Math.atan2((p.x + q.x) / 2, (p.y + q.y) / 2);
      const g = new T128.CircleGeometry(0.095, 8);
      g.rotateY(outward);
      add2(g, "dark", x, 5.995, z);
    }
  }
  const roof = new T128.BufferGeometry();
  roof.setAttribute("position", new T128.Float32BufferAttribute(vertices, 3));
  roof.computeVertexNormals();
  add2(roof, "slate");
  const underside = new T128.ShapeGeometry(new T128.Shape(outline));
  underside.rotateX(Math.PI / 2);
  add2(underside, "white", 0, 5.95, 0);
  cylinder(0.17, 7.02, 0.14, "dark");
  const bulb = new T128.SphereGeometry(0.29, 10, 6);
  bulb.scale(1, 1.25, 1);
  add2(bulb, "dark", 0, 7.45, 0);
  add2(new T128.ConeGeometry(0.14, 0.37, 8), "dark", 0, 7.77, 0);
  cylinder(0.027, 7.94, 0.06, "dark");
  for (let i = 0; i < 9; i++) {
    const y = i * floorHeight / 9, z = 6.48 - i * 0.35;
    box2(0, y, z, 1.9, floorHeight / 9, 0.38, "stone");
    for (const x of [-1.04, 1.04]) cylinder(0.028, y + 0.16, 0.9, "dark", x, z, 6);
  }
  for (const x of [-1.04, 1.04]) {
    beam([x, 1.1, 6.48], [x, 2.4, 3.68], 0.045, "dark");
    beam([x, 0.61, 6.48], [x, 1.91, 3.68], 0.025, "dark");
  }
}

