// scripts/landmarks/agnieten-builder.ts
function buildAgnietenkapel(_w, _d, b) {
  const [lng, lat] = agnieten_footprint_default.anchor, lon = 111320 * Math.cos(lat * Math.PI / 180);
  const point = (p2) => new T137.Vector2((p2[0] - lng) * lon, -(p2[1] - lat) * 110540);
  const ring = agnieten_footprint_default.parent.ring.slice(0, -1).map(point);
  const angle = (90 - agnieten_footprint_default.axisHeadingDegrees) * Math.PI / 180;
  const axis = new T137.Vector2(Math.cos(angle), -Math.sin(angle));
  const side = new T137.Vector2(Math.sin(angle), Math.cos(angle));
  const cross = (p2) => p2.dot(side);
  const peak = agnieten_footprint_default.heightMetres, eave = 10.8;
  const roofHeight = (p2) => Math.max(eave, peak - Math.abs(cross(p2) - 0.1) * 1.45);
  function surface(vertices, c) {
    const g = new T137.BufferGeometry();
    g.setAttribute("position", new T137.Float32BufferAttribute(vertices, 3));
    g.computeVertexNormals();
    b.add(g, c);
  }
  const body = new T137.ExtrudeGeometry(new T137.Shape(ring), { depth: eave, bevelEnabled: false });
  body.rotateX(Math.PI / 2);
  body.translate(0, eave, 0);
  b.add(body, "brick");
  const geometry = new T137.ShapeGeometry(new T137.Shape(ring)), p = geometry.getAttribute("position"), idx = geometry.getIndex();
  function clip(poly, limit, greater) {
    const out2 = [];
    for (let i = 0; i < poly.length; i++) {
      const a = poly[i], q = poly[(i + 1) % poly.length], da = cross(a) - limit, dq = cross(q) - limit;
      const inside = greater ? da >= -1e-8 : da <= 1e-8, next = greater ? dq >= -1e-8 : dq <= 1e-8;
      if (inside) out2.push(a);
      if (inside !== next) out2.push(a.clone().lerp(q, da / (da - dq)));
    }
    return out2;
  }
  const roofs = [];
  for (let k = 0; k < idx.count; k += 3) {
    let polys = [Array.from({ length: 3 }, (_, j) => new T137.Vector2(p.getX(idx.getX(k + j)), p.getY(idx.getX(k + j))))];
    for (const limit of [0.1 - (peak - eave) / 1.45, 0.1, 0.1 + (peak - eave) / 1.45]) polys = polys.flatMap((poly) => [clip(poly, limit, false), clip(poly, limit, true)].filter((q) => q.length >= 3));
    for (const poly of polys) for (let j = 1; j < poly.length - 1; j++) roofs.push(...[poly[0], poly[j], poly[j + 1]].flatMap((q) => [q.x, roofHeight(q), q.y]));
  }
  surface(roofs, "slate");
  for (let i = 0; i < ring.length; i++) {
    const a = ring[i], q = ring[(i + 1) % ring.length], v = q.clone().sub(a);
    const cuts = [0, 1];
    for (const limit of [0.1 - (peak - eave) / 1.45, 0.1, 0.1 + (peak - eave) / 1.45]) {
      const t = (limit - cross(a)) / (cross(q) - cross(a));
      if (t > 0 && t < 1) cuts.push(t);
    }
    cuts.sort((a2, c) => a2 - c);
    for (let j = 0; j < cuts.length - 1; j++) {
      const u = a.clone().addScaledVector(v, cuts[j]), z = a.clone().addScaledVector(v, cuts[j + 1]);
      surface([u.x, eave, u.y, z.x, eave, z.y, z.x, roofHeight(z), z.y, u.x, eave, u.y, z.x, roofHeight(z), z.y, u.x, roofHeight(u), u.y], "brick");
    }
  }
  function offset(q, a, forward, u = 0) {
    return new T137.Vector2(q.x + Math.sin(a) * forward + Math.cos(a) * u, q.y + Math.cos(a) * forward - Math.sin(a) * u);
  }
  function panel(q, y, w, h, a, c, pointed = false) {
    const s = new T137.Shape();
    s.moveTo(-w / 2, 0);
    s.lineTo(w / 2, 0);
    if (pointed) {
      s.lineTo(w / 2, h - w * 0.65);
      s.quadraticCurveTo(w * 0.3, h, 0, h);
      s.quadraticCurveTo(-w * 0.3, h, -w / 2, h - w * 0.65);
    } else {
      s.lineTo(w / 2, h - w / 2);
      s.absarc(0, h - w / 2, w / 2, 0, Math.PI, false);
    }
    s.closePath();
    b.add(new T137.ExtrudeGeometry(s, { depth: 0.12, bevelEnabled: false, curveSegments: 6 }), c, q.x, y, q.y, a);
  }
  function window2(q, y, w, h, a, pointed = false) {
    panel(q, y, w + 0.24, h + 0.24, a, "stone", pointed);
    panel(offset(q, a, 0.13), y + 0.12, w, h, a, "glass", pointed);
    const z = offset(q, a, 0.28);
    b.box(z.x, y + 0.18, z.y, 0.07, h - w * 0.6, 0.08, "dark", a);
    for (let v = 1; v < h - w * 0.55; v += 1.05) b.box(z.x, y + v, z.y, w, 0.07, 0.08, "dark", a);
  }
  const west = point([4.894868, 52.3699481]), east = ring[1].clone().add(ring[2]).multiplyScalar(0.5);
  const endEdge = ring[2].clone().sub(ring[1]);
  const westFace = angle - Math.PI / 2, eastFace = Math.atan2(endEdge.y, -endEdge.x);
  for (const u of [-1.3, 1.3]) window2(offset(west, westFace, 0.1, u), 5, 1.9, 7, westFace, true);
  const rose = offset(west, westFace, 0.28);
  for (const [r, c] of [[0.98, "stone"], [0.82, "glass"]]) {
    const g = new T137.CylinderGeometry(r, r, 0.12, 16);
    g.rotateX(Math.PI / 2);
    b.add(g, c, rose.x, 13.25, rose.y, westFace);
  }
  const door = offset(west, westFace, 0.2);
  b.box(door.x, 0, door.y, 1.8, 3, 0.2, "dark", westFace);
  for (const u of [-1.08, 1.08]) window2(offset(east, eastFace, 0.1, u), 3.7, 1.75, 6, eastFace);
  window2(offset(east, eastFace, 0.1), 11.1, 3.9, 4, eastFace);
  const endDoor = offset(east, eastFace, 0.1);
  b.box(endDoor.x, 0, endDoor.y, 1.7, 2.65, 0.2, "stone", eastFace);
  const inset = offset(east, eastFace, 0.26);
  b.box(inset.x, 0.08, inset.y, 1.4, 2.3, 0.18, "dark", eastFace);
  for (const t of [-5, 2, 7]) {
    const q = axis.clone().multiplyScalar(t).addScaledVector(side, -2.55);
    b.box(q.x, 14.9, q.y, 1.45, 1.5, 0.8, "brick", angle);
    const face2 = offset(q, angle + Math.PI, 0.45);
    b.box(face2.x, 15, face2.y, 1.05, 1.1, 0.12, "glass", angle + Math.PI);
  }
  const wall = agnieten_footprint_default.courtyardWall.ring.map(point), gate2 = wall[1], wa = wall[2].clone().sub(wall[0]).normalize();
  const face = -Math.atan2(wa.y, wa.x);
  const portalWidth = 2.7, spring = 2.05, radius = portalWidth / 2, wallHeight = 3.8;
  for (const end of [wall[0], wall[2]]) {
    const length = end.distanceTo(gate2) - portalWidth / 2, mid = gate2.clone().lerp(end, (portalWidth / 2 + length / 2) / gate2.distanceTo(end));
    b.box(mid.x, 0, mid.y, length, wallHeight, 0.38, "brick", face);
    b.box(mid.x, wallHeight, mid.y, length, 0.14, 0.52, "stone", face);
  }
  const arch3 = new T137.Shape();
  arch3.absarc(0, spring, radius + 0.32, 0, Math.PI, false);
  arch3.lineTo(-radius, spring);
  arch3.absarc(0, spring, radius, Math.PI, 0, true);
  arch3.closePath();
  b.add(new T137.ExtrudeGeometry(arch3, { depth: 0.45, bevelEnabled: false, curveSegments: 12 }), "stone", gate2.x, 0, gate2.y, face);
  for (const u of [-radius - 0.22, radius + 0.22]) {
    const q = offset(gate2, face, 0, u);
    b.box(q.x, 0, q.y, 0.45, spring, 0.5, "stone", face);
    b.box(q.x, 2.9, q.y, 0.55, 1.4, 0.5, "stone", face);
    for (const y of [0.3, 1.3, 2.15, 3.7]) b.box(q.x, y, q.y, 0.65, 0.15, 0.62, "stone", face);
    b.add(new T137.SphereGeometry(0.23, 6, 4), "stone", q.x, 4.45, q.y);
    b.add(new T137.ConeGeometry(0.16, 0.35, 6), "stone", q.x, 4.81, q.y);
  }
  const top = offset(gate2, face, 0.06);
  b.box(top.x, 3.55, top.y, 3.6, 0.25, 0.5, "stone", face);
  b.box(top.x, 3.8, top.y, 1.9, 0.45, 0.5, "stone", face);
  b.box(top.x, 4.15, top.y, 1.35, 1.3, 0.42, "stone", face);
  const shield = offset(gate2, face, 0.33);
  b.box(shield.x, 4.32, shield.y, 0.62, 0.95, 0.12, "red", face);
  for (const y of [4.52, 4.8, 5.08]) for (const a of [-Math.PI / 4, Math.PI / 4]) {
    const g = new T137.BoxGeometry(0.36, 0.065, 0.06);
    g.rotateZ(a);
    b.add(g, "white", shield.x, y, shield.y + 0.08, face);
  }
  for (const u of [-1.12, 1.12]) {
    const q = offset(gate2, face, 0.06, u);
    b.add(new T137.TorusGeometry(0.36, 0.09, 4, 10, Math.PI * 1.65), "stone", q.x, 4.3, q.y, face);
  }
  b.add(new T137.SphereGeometry(0.23, 8, 5), "stone", top.x, 5.63, top.y);
  for (let u = -1.15; u <= 1.15; u += 0.23) {
    const q = offset(gate2, face, 0.13, u);
    b.box(q.x, 0, q.y, 0.055, spring + Math.sqrt(Math.max(0, radius * radius - u * u)), 0.07, "dark", face);
  }
  for (const y of [1, 2.02]) {
    const q = offset(gate2, face, 0.14);
    b.box(q.x, y, q.y, portalWidth, 0.06, 0.08, "dark", face);
  }
}

