// scripts/landmarks/occii-facade-banner.ts
import * as T138 from "three";
function buildOcciiBanner(b, cx2, f, angle) {
  const y = 3.38, w = 2.25, h = 0.76;
  b.box(cx2, y, f(cx2) + 0.46, w, h, 0.07, "white", angle);
  const polygon = (points) => {
    const s = new T138.Shape();
    points.forEach(([x2, y2], i) => i ? s.lineTo(x2, y2) : s.moveTo(x2, y2));
    s.closePath();
    return s;
  };
  const draw = (s, x2) => b.add(new T138.ShapeGeometry(s), "red", x2, 3.54, f(x2) + 0.51, angle);
  const outer = [[0.04, 0], [0, 0.07], [0, 0.39], [0.07, 0.48], [0.22, 0.48], [0.28, 0.41], [0.28, 0.07], [0.22, 0]];
  const inner = [[0.075, 0.09], [0.075, 0.36], [0.11, 0.4], [0.19, 0.4], [0.205, 0.36], [0.205, 0.1], [0.18, 0.08], [0.11, 0.08]];
  const glyphs = ["O", "C", "C", "I", "I"], widths = [0.28, 0.28, 0.28, 0.14, 0.14], tracking = 0.1;
  let x = cx2 - (widths.reduce((a, c) => a + c, 0) + tracking * 4) / 2;
  for (let i = 0; i < glyphs.length; i++) {
    const letter = glyphs[i];
    if (letter === "O") {
      const s = polygon(outer), hole = new T138.Path();
      inner.forEach(([xx, yy], j) => j ? hole.lineTo(xx, yy) : hole.moveTo(xx, yy));
      hole.closePath();
      s.holes.push(hole);
      draw(s, x);
    } else if (letter === "C") draw(polygon([[0.27, 0.41], [0.21, 0.48], [0.07, 0.48], [0, 0.39], [0, 0.07], [0.04, 0], [0.22, 0], [0.28, 0.07], [0.22, 0.14], [0.18, 0.08], [0.11, 0.08], [0.075, 0.11], [0.075, 0.36], [0.11, 0.4], [0.18, 0.4], [0.22, 0.34]]), x);
    else draw(polygon([[0, 0.04], [0.045, 0], [0.14, 0.06], [0.1, 0.1], [0.1, 0.38], [0.14, 0.43], [0.095, 0.48], [0, 0.42], [0.04, 0.37], [0.04, 0.1]]), x);
    x += widths[i] + tracking;
  }
  for (let i = 0; i < 16; i++) b.add(new T138.CircleGeometry(0.055, 8), "red", cx2 - w / 2 + 0.08 + i * (w - 0.16) / 15, y + 0.035, f(cx2 - w / 2 + 0.08 + i * (w - 0.16) / 15) + 0.51, angle);
}

