      sh.lineTo(9.02, 7.35);
      sh.closePath();
      const g = new T139.ShapeGeometry(sh);
      g.rotateY(side * Math.PI / 2);
      add2(g, "brick", side * 11.59, 0, 0);
      for (const [z0, y0, z1, y1] of [[-9, 7.35, -5.6, 11.25], [-5.6, 11.25, 0, 13.4], [0, 13.4, 5.6, 11.25], [5.6, 11.25, 9, 7.35]]) beam(side * 11.72, y0, z0, side * 11.72, y1, z1, 0.23, "stone");
