    arch3(x, 0, 26.43, 2.78, 4.35, 0, "stone");
    arch3(x, 0.08, 26.51, 2.4, 4, 0, "dark");
    box2(x, 0.12, 26.64, 0.1, 3.33, 0.07, "stone");
