    add2(new T154.CircleGeometry(0.36, 16), "stone", x, 6.15, 26.48);
    for (const u of [-1.08, -0.72, -0.36, 0.36, 0.72, 1.08]) box2(x + u, 0.15, 26.69, 0.045, 1.8, 0.06, "frame");
